"""Add independent explanations to the 16 modeling lessons; never rewrite sources.

Default mode validates the draft. Use --write only after pilot UI approval.
The authored explanations below are specific to course-pack examples. PDF page
references point to the separately supplied lecturer PDFs, not to this app pack.
"""
import argparse
import copy
import hashlib
import json
import sqlite3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE_PATH = ROOT / 'content/course-pack.json'
SOURCE_BYTES = SOURCE_PATH.read_bytes()
PACK = json.loads(SOURCE_BYTES)
LESSONS = {l['id']: l for l in PACK['lessons']}
GUIDES = {}
DEFICIENCIES = {
 '1-1-01':'기존 SELECT 설명에 행별 참·거짓 대입표와 처음 등장한 ORDER BY의 뜻·오름차순 전제가 부족했다.',
 '1-1-02':'점수를 수강표에 둔다는 결론은 있었지만 양선규의 DB90/JAVA80을 대비해 소속을 판단하는 과정이 짧았다.',
 '1-1-03':'물리 단계의 NUMBER(6), VARCHAR2(30 CHAR), PK·필수의 의미를 숫자·대상별로 구분하는 안내가 부족했다.',
 '1-1-04':'사용자별 결과표는 있었으나 생략된 열의 원본 유지와 변경 대상별 논리적·물리적 독립성 비교가 짧았다.',
 '1-1-05':'M:N의 결론은 있었으나 학생 한 명→여러 과목과 과목 하나→여러 학생을 따로 따라가는 중간표가 없었다.',
 '1-1-06':'종류·행·열을 구별하지만 속성값과 동명이인, 엔터티 분류의 서로 다른 축을 연결하는 추가 질문이 부족했다.',
 '1-1-07':'차수·튜플 수는 정확했으나 현재 관측값과 허용 도메인, 원자성의 업무 조건을 비교하는 예가 부족했다.',
 '1-1-08':'FK 반복은 설명하지만 두 학과코드의 소속·참조 방향과 필수 참여/식별 관계/삭제 정책의 구분이 부족했다.',
 '1-1-09':'복합 식별자 결과는 있었으나 학번만·과목만 지정했을 때 실제로 남는 두 행과 PK 하나의 다중 컬럼 의미가 짧았다.',
 '1-2-01':'행·열 수는 정확했으나 행 추가와 열 추가의 전후 비교, 같은 학과값과 행 전체 중복의 칸별 비교가 부족했다.',
 '1-2-02':'키 분류는 정확했으나 후보별 최소성 검사표와 원본에 빠진 부모 학과표의 검증 한계가 명시적이지 않았다.',
 '1-2-03':'허용/거절 이유는 있었으나 입력 시도와 저장된 상태를 분리한 표, 학생 쪽 FK 소속, DEFAULT/NULL의 차이를 더 연결할 필요가 있었다.',
 '1-2-04':'분류 결과는 있었으나 각 명령이 바꾸는 대상과 완전한 실행문 부재, DBMS별 DDL 커밋 차이 설명이 짧았다.',
 '1-2-05':'원본 결과가 강의실301→401을 이미 반영해 분해 자체의 결과로 오해할 수 있었다. 잘못된 갱신 중간 상태와 재연결 확인이 필요했다.',
 '1-2-06':'종속·BCNF 정의는 정확했으나 2NF 중간 학생표, 두 후보키 도출과 3NF/BCNF 판정표, 무손실/종속보존 차이의 구체화가 필요했다.',
 '1-2-07':'SELECT의 저장합계 별칭을 실제 저장으로 오인할 위험이 있었다. 실제 조회 결과와 저장·변경 가정의 상태표를 구별할 필요가 있었다.',
}
CONSTRAINT = 'https://docs.oracle.com/en/database/oracle/oracle-database/19/sqlrf/constraint.html'
MODEL = 'https://docs.oracle.com/en/database/oracle/sql-developer-data-modeler/24.3/dmdug/data-modeler-concepts-usage.html'
INTRO = 'https://docs.oracle.com/en/database/oracle/oracle-database/19/cncpt/introduction-to-oracle-database.html'
NORMAL = 'https://www.db-book.com/slides-dir/PDF-dir/ch7.pdf'
COMMIT = 'https://docs.oracle.com/en/database/oracle/oracle-database/19/sqlrf/COMMIT.html'
TYPES = 'https://docs.oracle.com/en/database/oracle/oracle-database/19/sqlrf/Data-Types.html'

def table(title, columns, rows):
    return dict(title=title, columns=columns, rows=rows)

def step(title, text, t=None, focus=(), marks=(), rows=(), cells=()):
    assert not isinstance(focus, str) and not isinstance(marks, str), 'Use a sequence, never split a string into characters'
    return dict(title=title, text=text, codeFocus=[dict(needle=s, occurrence=0) for s in focus],
                highlights=list(marks), table=t, focusRows=list(rows), focusCells=list(cells))

def result(lid, ex=0, n=0):
    return copy.deepcopy(LESSONS[lid]['examples'][ex]['results'][n])

def original(lid, ex=0, n=0):
    return copy.deepcopy(LESSONS[lid]['examples'][ex]['tables'][n])

def example(lid, n, why, effect, prerequisites, steps, comparison, verification=None):
    ex = LESSONS[lid]['examples'][n]
    for i, s in enumerate(steps, 1):
        s['id'] = f'read-{i:02}'
    return dict(exampleId=ex['id'], why=why, effect=effect, prerequisites=prerequisites,
                steps=steps, comparison=comparison,
                verification=verification or '원본 표·업무 규칙과 추가 설명을 대조한 개념 검토입니다. SQL을 실행하는 예제가 아닙니다. 실제 DBMS 실행·사람 전문가 검수는 하지 않았습니다.')

def term(token, kind, meaning, role):
    return dict(token=token, kind=kind, meaning=meaning, role=role)

def lesson(lid, purpose, overview, page_range, examples, checks, questions, pitfalls=(), extra_terms=(), notes=(), sources=()):
    l = LESSONS[lid]
    assert len(checks) == len(l['selfChecks'])
    terms = [term(x['term'], '개념', x['meaning'], x['example']) for x in l['concepts']]
    for t in extra_terms:
        terms = [existing for existing in terms if existing['token'] != t['token']]
        terms.append(t)
    GUIDES[lid] = dict(schemaVersion=1, lessonId=lid, source=copy.deepcopy(l), purpose=purpose,
        overview=overview, terms=terms, pitfalls=list(pitfalls),
        questions=[dict(question=q, answer=a) for q,a in questions],
        pdfRefs=[dict(sectionId=l['partId'], title='데이터 모델링의 이해' if l['partId']=='1-1' else '데이터 모델과 SQL',
                      fromPage=page_range[0], toPage=page_range[1],
                      note='흥달쌤 원본 PDF의 해당 단원과 문제를 대조했습니다. 아래 앱 예제의 이름·표·값은 PDF 문제와 별도 데이터이며, 원본 PDF의 보기를 옮겨 채점하지 않습니다.')],
        examples=examples,
        checkGuides=[dict(checkId=q['id'],hint=h,reasoning=r) for q,(h,r) in zip(l['selfChecks'],checks)],
        sourceUrls=list(sources), reviewNotes=list(notes))

lid='1-1-01'
lesson(lid, '컴퓨터 학과 성적을 볼 때 저장된 학생 정보와 그것을 읽어 주는 프로그램을 구별하자.',
 '학생표를 읽어 필요한 이름·점수를 보여 주는 조회다. 학생표를 만들거나 장정훈의 행을 삭제하는 작업은 아니다. SQL 문법은 뒤 단원에서 배우므로 여기서는 각 단어의 역할부터 함께 읽는다.', (1,3), [
 example(lid,0,'학과 담당자가 컴퓨터 학과 학생의 성적만 확인하려는 상황이다.','조회: 학생표의 일부 행·열을 결과로 표시한다.',
 ['학생표는 이미 있고 학번·이름·학과·점수 네 열과 박상현·장정훈·박보성의 세 행이 저장되어 있다.','SQL의 학과 조건과 이름·점수는 모두 이 학생표의 열이다. 작은따옴표 속 컴퓨터는 열 이름이 아니라 비교할 문자열이다.'],[
 step('전체 목적과 조회 대상','SELECT 이름, 점수는 최종 화면에 보여 줄 두 항목이다. FROM 학생은 이 항목들을 읽어 올 표를 정한다. DB는 이 학생 데이터이고 DBMS는 요청을 받아 조건을 확인하고 결과를 돌려주는 프로그램이다.',original(lid),('SELECT 이름, 점수','FROM 학생'),('이름, 점수','FROM 학생')),
 step('학생의 학과값을 한 행씩 대입','박상현의 컴퓨터는 조건과 같아 참, 장정훈의 전자는 달라 거짓, 박보성의 컴퓨터는 같아 참이다. 참인 두 행만 조회 후보에 남긴다. 장정훈의 원본 행은 유지된다.',table('학습용 조건 판정',['학번','이름','학과','판정'],[['1001','박상현','컴퓨터','참 · 통과'],['1002','장정훈','전자','거짓 · 제외'],['1003','박보성','컴퓨터','참 · 통과']]),("WHERE 학과='컴퓨터'",),('장정훈의 원본 행은 유지',),(0,2)),
 step('필요한 열과 정렬을 구분','통과한 1001번 박상현과 1003번 박보성에서 이름·점수만 표시한다. ORDER BY 학번은 학번이 작은 순으로 정렬한다. ASC를 생략한 오름차순이며 최종 화면에 학번 열이 없어도 이 쿼리는 학번으로 정렬한다.',result(lid),('ORDER BY 학번',),('이름·점수','학번이 작은 순')),
 step('그림과 실제 표를 연결해서 읽기','기존 DBMS 그림에서는 요청 → DBMS → 저장소 → 결과의 역할을 따라가자. 그림의 유성재·박강열 학생표와 지금 박상현·장정훈·박보성 표는 별개다. 현재 쿼리 후 원본 세 행과 네 열은 그대로이고 조회 결과만 두 행·두 열이다.',table('조회 전후 비교',['대상','이전','이후'],[['원본 학생표','3행 · 4열','유지 · 3행 · 4열'],['조회 화면','아직 없음','박상현 90 / 박보성 80']]),marks=('원본 세 행과 네 열은 그대로',))
 ],'DB와 DBMS, 조건으로 결과에서 제외하는 일과 DELETE로 원본을 지우는 일을 구분한다. 위 순서는 학습용 논리 설명이며 DB의 실제 실행계획을 측정한 순서가 아니다.')],
 [('저장된 기록인지, 기록을 다루는 프로그램인지 생각해 보자.','Oracle 제품을 말하는 이 문항에서는 DBMS다. 학생표의 값을 보관·조회·관리하는 소프트웨어이지 박상현의 90이라는 데이터 자체가 아니다.'),('숫자 자체와 비교 기준을 붙인 문장을 나눠 보자.','90은 기록된 점수다. 평균보다 10점 높다는 표현은 평균과 비교해 얻은 의미라 정보다. 평균값은 원본 조회표에서 계산한 것이 아니라 확인문제의 별도 전제다.'),('원본을 바꾸는 명령인지 결과를 보여 주는 명령인지 먼저 보자.','SELECT이므로 장정훈의 학번 1002·전자·70은 원본에 남는다. 조건을 만족하지 않아 이번 조회 화면에 나오지 않을 뿐이다.')],
 [('FROM이 뭔데?','FROM은 어디에서라는 뜻이다. FROM 학생은 이미 있는 학생표를 조회 대상으로 삼는다.'),('학과와 컴퓨터는 둘 다 컬럼이야?','학과는 컬럼명, 작은따옴표로 감싼 컴퓨터는 비교할 값이다. 각 학생의 학과 칸을 그 값과 비교한다.'),('사진도 데이터야?','그렇다. 이 예제는 행·열이 정해진 정형 데이터다. 사진·음성 같은 비정형 데이터, JSON처럼 구조가 있지만 고정된 표는 아닌 반정형 데이터도 있다.')],
 ['SQL은 DBMS에 보내는 요청 문법이며 저장 장치 이름이 아니다. 모든 DB가 관계형 테이블만 쓰는 것은 아니다.','처음 등장한 ORDER BY는 정렬이다. 이 문법을 아직 몰랐다면 DB·DBMS 개념을 틀리게 이해한 것으로 취급하지 않는다.'],
 [term('SELECT','키워드','선택하여 보여 주다','이름·점수 두 열을 조회 결과에 표시한다.'),term('FROM','키워드','어디에서','학생표에서 값을 가져온다.'),term('WHERE','키워드','어떤 조건에서','학생.학과가 컴퓨터인 행을 선택한다.'),term('ORDER BY','키워드','무엇을 기준으로 정렬','학번의 오름차순을 정한다.'),term('학생','테이블명','이 예제에서 설계한 표 이름','학번·이름·학과·점수의 원래 저장 위치다.'),term("'컴퓨터'",'문자열 값','작은따옴표는 문자열을 감싼다','학과 컬럼값과 비교할 기준이다.')],
 ['PDF 1쪽의 테이블 중심 DB 설명은 관계형 DB 문맥으로 한정했다. 다른 DB 유형까지 모두 테이블형이라고 확장하지 않았다.'],[INTRO])

lid='1-1-02'
lesson(lid,'같은 학생이 DB와 JAVA에서 다른 점수를 받을 때 점수를 어느 표에 두어야 하는지 설명하자.',
 'SQL 실행이 아니라 저장 구조를 정하는 설계다. 학생 자체, 과목 자체, 어느 학생이 어느 과목에서 받은 점수라는 세 사실을 나누어 본다.',(3,5),[
 example(lid,0,'양선규의 이름을 DB 수강 기록과 JAVA 수강 기록마다 따로 고치지 않도록 설계한다.','개념: 학생·과목·수강이라는 저장 대상과 각 속성의 소속을 정한다.',
 ['결과표에 제시된 학생 1001 양선규·1002 한창주, 과목 C01 DB·C02 JAVA, 세 수강 기록을 그대로 사용한다.','학번으로 학생을, 과목코드로 과목을 구별하며 이름만으로 연결하지 않는 설계다.'],[
 step('문장에서 대상과 연결을 나누기','학생은 사람을 관리하는 대상이고 과목은 수업을 관리하는 대상이다. 수강하고 점수를 받는다는 말은 두 대상 사이의 연결에 붙는 사실이다. 현실의 모든 정보를 저장하지 않고 이 업무에 필요한 사실을 뽑는 것이 추상화다.',original(lid),marks=('학생','과목','연결')),
 step('학생에게만 속한 정보 찾기','학생표의 (1001, 양선규)는 한 학생의 학번과 이름을 묶은 행이다. 양선규가 DB와 JAVA를 둘 다 수강해도 이름은 학생표 한 곳에서 관리한다. 과목명은 학생의 고정된 속성이 아니므로 이 표에 넣지 않는다.',result(lid,0,0),marks=('1001, 양선규',),rows=(0,)),
 step('과목의 이름은 과목표에서 관리','과목코드 C01은 DB, C02는 JAVA를 뜻한다. 여러 학생이 DB를 들어도 과목명은 C01 한 행으로 관리한다. 학생의 이름과 과목의 이름은 서로 다른 대상에 속한 속성이다.',result(lid,0,1),marks=('C01','C02')),
 step('점수의 소속을 실제 두 행으로 확인','1001의 C01 점수는 90이고 C02 점수는 80이다. 학번 1001만 알면 90인지 80인지 결정할 수 없으므로 점수는 학생표가 아니라 수강표에 둔다. (1002,C01,70)은 한창주의 DB 수강이다.',result(lid,0,2),marks=('1001의 C01 점수는 90','C02 점수는 80'),rows=(0,1)),
 step('그림을 읽은 뒤 예제를 다시 연결','기존 모델링 그림의 현실 문장 → 대상·관계 → 속성·키 → 자료형 순서를 따라가자. 그림은 박강열의 가상 수강이고 현재 표는 양선규·한창주다. 이 예제에서는 수강의 학번을 학생표, 과목코드를 과목표에서 찾아 이름·과목명을 복원한다.',table('설명용 연결 확인',['수강의 키','학생표에서 찾음','과목표에서 찾음','점수'],[['1001 / C01','양선규','DB','90'],['1001 / C02','양선규','JAVA','80'],['1002 / C01','한창주','DB','70']]),marks=('수강의 학번','과목코드'))
 ],'학생 이름은 학생 속성, 점수는 학생과 과목의 연결에 속한 속성이다. 점수를 사람 이름만으로 연결하면 동명이인을 구별하지 못한다.')],
 [('관리 대상의 종류와 그 대상을 설명하는 항목을 나눠 보자.','학생은 엔터티이고 이름은 학생을 설명하는 속성이다. 양선규라는 문자열은 특정 학생의 이름 속성값이다.'),('1001번 학생의 DB와 JAVA 점수가 같은지 보자.','1001의 점수는 C01에서 90, C02에서 80으로 다르다. 학생과 과목을 함께 알아야 정해지므로 수강표에 둔다.'),('성적 관리에 반드시 필요한 사실인지부터 생각해 보자.','현실을 그대로 복사하지 않고 업무에 필요한 사실을 고른다. 이 예제에서는 학번·이름·과목·점수가 필요하고 학생의 오늘 옷 색은 필요하지 않다.')],
 [('수강도 엔터티야?','이 설계에서는 그렇다. 누가 어느 과목을 듣는지와 점수를 지속적으로 관리하므로 연결 자체를 수강이라는 대상으로 만든다.'),('모델링의 세 관점은?','데이터 관점은 학생·과목·점수가 무엇인지, 프로세스 관점은 수강신청·성적입력이 어떤 일인지, 상관 관점은 성적입력이 수강.점수를 어떻게 바꾸는지 본다.')],
 ['개념적 관계가 있다는 말과 실제 DB에 FOREIGN KEY 제약이 이미 만들어졌다는 말은 다르다.','같은 사실의 불필요한 반복을 줄이는 것이지 모든 값의 반복을 금지하는 설계가 아니다.'],sources=[MODEL])

lid='1-1-03'
lesson(lid,'학번 중복 금지와 이름 필수라는 요구가 어떻게 실제 정의로 구체화되는지 구별하자.',
 '학생표의 값을 바꾸는 과정이 아니라 설계를 구체화하는 세 단계다. 각 단계의 산출물은 같은 학생 관리 요구를 서로 다른 상세 수준으로 표현한다.',(5,7),[
 example(lid,0,'학번은 중복되면 안 되고 이름은 빠지면 안 된다는 요구를 설계자가 받았다.','개념: 요구사항에서 논리 규칙과 Oracle 물리 정의로 구체화한다.',
 ['이 예제는 실행할 CREATE TABLE 문이 아니라 단계별 산출물을 비교하는 표다.','학번 NUMBER(6)와 이름 VARCHAR2(30 CHAR)는 Oracle 기준 물리 설계 예시다.'],[
 step('먼저 저장할 사실과 업무 규칙','요구에는 학생의 학번과 이름이 있다. 학번 중복 금지는 학생을 구별해야 한다는 요구이고 이름 필수는 입력값을 빠뜨리지 않겠다는 별도 요구다. 아직 몇 행이 저장될지는 정하지 않는다.',original(lid),marks=('학번 중복 금지','이름 필수')),
 step('개념 단계: 학생이라는 대상','먼저 관리 대상이 학생이라는 점을 정한다. 현실에서 필요하지 않은 특징은 제외한다. 이 단계에서 학생이라는 이름을 적는 것은 DB에 학생 행을 입력한 것이 아니다.',table('개념 단계',['결정할 내용','이 예제'],[['관리 대상','학생'],['업무 요구','학생을 구별하고 이름을 기록']]),marks=('관리 대상이 학생',)),
 step('논리 단계: 항목과 식별 규칙','학생(학번 PK, 이름 필수)에서 학번·이름은 두 항목이고 PK는 학번을 대표 식별자로 삼는다는 표시다. 이름 필수는 이름이 유일하다는 뜻이 아니다. 동명이인 허용 여부와 필수 여부는 서로 다른 규칙이다.',table('논리 단계',['속성','규칙','이유'],[['학번','주식별자','학생 한 명 구별'],['이름','필수','누구인지 이름 기록']]),marks=('학번·이름','이름 필수')),
 step('물리 단계: 숫자는 행 수가 아니다','NUMBER(6)의 6은 학번 숫자의 정밀도 제한이다. 학생 여섯 명이나 자동 일련번호라는 뜻이 아니다. 이 예시의 NUMBER(6)은 소수 자릿수 0으로 취급되어 소수 입력은 반올림될 수 있고 반올림한 값이 정밀도를 넘으면 오류다. VARCHAR2(30 CHAR)의 30은 이름 문자열의 문자 수 기준 길이다.',result(lid),marks=('숫자의 정밀도 제한','문자 수 기준 길이')),
 step('개념도에서 무엇이 늘어났는지 보기','기존 모델링 그림의 학생이라는 대상에서 학번·이름으로, 다시 NUMBER·VARCHAR2·PRIMARY KEY로 구체화되는 부분을 보자. 설계 설명이 상세해진 것이며 데이터를 세 번 따로 저장하는 동작은 아니다.',table('단계마다 새로 정한 것',['단계','추가한 결정'],[['개념','학생이라는 관리 대상'],['논리','학번으로 식별 · 이름 필수'],['물리','Oracle 자료형과 실제 제약 정의']]),marks=('설계 설명이 상세해진',))
 ],'논리적 모델링은 어떤 사실과 규칙을 저장할지, 물리적 모델링은 선택한 DBMS에서 이를 어떻게 정의할지 정한다. 논리 모델링과 논리적 독립성은 서로 다른 질문이다.')],
 [('제품별 저장 방식인지, 표의 논리 규칙인지 살펴보자.','식별자와 정규화는 학생·수강 같은 표의 논리 구조를 정하므로 논리적 모델링에 가깝다.'),('NUMBER와 인덱스가 특정 DBMS에서 쓰이는 정의인지 생각해 보자.','물리적 모델링이다. 학생이라는 개념을 찾는 단계를 넘어 실제 자료형·인덱스·저장 방법을 정한다.'),('형식의 길이를 고르기 전에 어떤 정보를 왜 저장해야 할까?','저장할 사실과 업무 규칙을 먼저 확인한다. 이 예제에서는 학번으로 학생을 구별하고 이름을 빠뜨리지 않는다는 요구다.')],
 [('PK면 이름도 중복 금지야?','아니다. 여기서 PK 대상은 학번이다. 이름의 필수 조건은 값을 빠뜨리지 말라는 규칙이다.'),('NUMBER(6)은 6자리만 넣어야 해?','아니다. 1001처럼 작은 정수도 가능하다. 정확히 여섯 자리를 강제하거나 번호를 자동 생성하는 설정이 아니다.'),('CHAR 없는 VARCHAR2(30)도 무조건 한글 30글자야?','아니다. BYTE/CHAR와 길이 의미 설정을 확인해야 한다. 이 원본 예시는 CHAR를 명시했다.')],
 ['이 강의의 정의 조각은 독립 실행문이 아니다. CREATE TABLE 전체 문장은 SQL 기본 단원에서 배운다.'],sources=[MODEL,TYPES])

lid='1-1-04'
lesson(lid,'교수와 행정실이 같은 학생표를 보면서 필요한 열만 다르게 보는 이유를 이해하자.',
 '학생 데이터를 변경하지 않고 사용자 관점·전체 논리 구조·실제 저장 방법을 나누어 설명한다. 스키마 3단계는 사용 중인 DB를 보는 관점이다.',(8,9),[
 example(lid,0,'교수는 성적을, 행정실은 학과를 확인해야 한다. 각 업무에 필요한 정보만 제공한다.','개념: 같은 원본에 대한 사용자별 구조와 저장 관점을 비교한다.',
 ['원본 학생은 학번·이름·학과·점수 네 열이며 1001 박강열 컴퓨터 90, 1002 이승현 전자 80의 두 행이다.','아래 사용자별 표는 관점을 설명한 것이며 CREATE VIEW를 실제 실행한 결과가 아니다.'],[
 step('전체 학생 구조부터 확인','개념 스키마에서는 학번·이름·학과·점수 전체와 식별·참조 같은 규칙을 다룬다. 박강열의 90 한 값만이 스키마인 것은 아니다. 그 값이 점수라는 항목에 들어간다는 구조가 핵심이다.',original(lid),marks=('학번·이름·학과·점수','구조')),
 step('교수의 외부 관점','교수에게 필요한 열은 이름과 점수다. 박강열 90, 이승현 80을 보여 주고 학과는 이 결과에서 생략한다. 학과 열을 원본에서 삭제한 것은 아니다.',result(lid,0,0),marks=('이름과 점수',)),
 step('행정실의 외부 관점','행정실은 박강열이 컴퓨터, 이승현이 전자 학과라는 정보를 본다. 같은 사람을 대상으로 해도 필요한 열이 다르므로 외부 스키마는 여러 개일 수 있다.',result(lid,0,1),marks=('컴퓨터','전자')),
 step('내부 관점과 독립성을 구분','파일·데이터 페이지·인덱스는 저장하고 찾는 방법이다. 인덱스를 바꾸어도 교수에게 이름·점수를 계속 제공하면 물리적 변경으로부터 논리 구조를 분리한 것이다. 학생표를 분해한 뒤 같은 조회 관점을 유지하는 것은 논리적 독립성 사례다.',table('변경과 유지',['바뀌는 부분','유지하려는 부분','독립성'],[['파일·인덱스','학생표의 논리 구조','물리적'],['학생표의 분해','교수의 이름·점수 관점','논리적']]),marks=('물리적','논리적')),
 step('기존 그림은 위에서 아래로','스키마 그림에서 두 사용자 화면을 먼저 보고 가운데 전체 논리 구조, 아래 파일·인덱스 순으로 내려가자. 화살표는 관점의 대응을 뜻한다. 개념→논리→물리라는 설계 작업 순서와 이 외부→개념→내부 관점을 같은 이름으로 외우지 않는다.',marks=('관점의 대응','외부→개념→내부'))
 ],'이름·점수라는 화면 구성과 실제로 학생표 열을 삭제하는 ALTER는 다르다. 외부 스키마와 물리적 화면 디자인 자체도 같은 개념은 아니다.')],
 [('누가 필요한 정보만 보는지, 저장 방법을 바꾸는지 구분해 보자.','교수라는 사용자의 필요한 데이터 관점이므로 외부 스키마다. 원본 전체 구조를 다루는 개념 스키마와 다르다.'),('인덱스는 논리적인 학생 속성인가, 저장·접근 방법인가?','인덱스는 내부 저장·접근 쪽이다. 이를 바꾸어도 학생의 학번·이름 같은 정의를 유지하는 것이 물리적 독립성이다.'),('분해되는 것은 전체 표 구조이고 유지되는 것은 사용자 관점이다.','개념 스키마 변경을 외부 관점에서 흡수하므로 논리적 독립성 사례다. 자동으로 항상 가능한 것이 아니라 매핑·뷰 등 설계가 필요하다.')],
 [('외부 스키마가 두 개면 DB도 두 개야?','아니다. 하나의 학생 DB를 교수는 이름·점수로, 행정실은 이름·학과로 볼 수 있다.'),('화면에 안 보이면 데이터가 없어진 거야?','아니다. 이 예제는 필요한 열만 보여 주는 관점이다. 두 원본 행의 학과·점수 모두 유지된다.')],
 ['데이터 독립성은 변경 영향을 줄이는 설계 능력이며 어떤 변경에도 프로그램 수정이 절대 없다는 보장은 아니다.'],sources=[MODEL])

lid='1-1-05'
lesson(lid,'양지훈이 두 과목을 듣고 DB를 두 학생이 듣는 관계를 양쪽 방향으로 읽어 보자.',
 'ERD는 구조와 업무 규칙을 표현한다. 수강표는 학생·과목 사이의 각각의 연결을 한 행에 저장한다. 선만으로 자동 JOIN이나 데이터 입력이 실행되지는 않는다.',(10,12),[
 example(lid,0,'학생표에 과목 이름을 한 칸에 나열하지 않고 수강 사실을 별도 관리한다.','개념: 학생과 과목의 M:N을 수강이라는 연결표로 표현한다.',
 ['학생 1001 양지훈·1002 박강열, 과목 C01 DB·C02 JAVA다. 원본 수강 결과는 (1001,C01),(1001,C02),(1002,C01) 세 행이다.','이 예제에서 같은 학생이 같은 과목을 한 번만 듣는 수강 범위를 가정한다. 재수강 이력은 학기 등 식별 조건을 추가 검토한다.'],[
 step('학생 한 명을 기준으로 선 읽기','학번 1001 양지훈은 C01 DB와 C02 JAVA를 듣는다. 학생 한 명에서 수강 행 두 개로 갈 수 있으므로 학생 쪽에서 보면 여러 과목과 연결된다.',table('양지훈의 연결',['학생','수강의 학번','수강의 과목코드','과목명'],[['1001 양지훈','1001','C01','DB'],['1001 양지훈','1001','C02','JAVA']]),marks=('학번 1001','수강 행 두 개')),
 step('이번에는 과목 하나에서 반대로','C01 DB에는 1001 양지훈과 1002 박강열이 연결된다. 과목 하나에서 학생도 여러 명이므로 양쪽 모두 다수인 M:N 관계다. 현재 그림의 선 수만이 아니라 업무상 허용할 수를 정한다.',table('DB 과목의 연결',['과목','수강의 학번','학생명'],[['C01 DB','1001','양지훈'],['C01 DB','1002','박강열']]),marks=('1001 양지훈','1002 박강열')),
 step('연결 한 건이 수강 한 행','(1001,C01)은 양지훈-DB 연결 하나다. (1001,C02)는 같은 학생의 다른 수강이고 (1002,C01)은 다른 학생의 DB 수강이다. 학번 하나나 과목코드 하나의 중복은 허용하되 두 값의 조합으로 연결을 구별한다.',result(lid),marks=('두 값의 조합',)),
 step('ERD 기호와 최소 참여수','학생·과목은 수강을 0건 또는 여러 건 가질 수 있다는 업무 규칙이면 0..N으로 쓴다. 수강 한 행은 학생 한 명·과목 하나를 가리킨다. N은 최대 수의 다수, 0은 없어도 됨을 뜻하므로 두 정보를 따로 읽는다.',table('관계 읽기',['기준 하나','상대','이 설명의 범위'],[['학생','수강 0..N','수강 전 학생도 허용'],['과목','수강 0..N','신설 과목도 허용'],['수강','학생 1 · 과목 1','연결 한 건의 양 끝']]),marks=('N은 최대 수의 다수','0은 없어도 됨')),
 step('기존 ERD 그림 읽는 법','기존 그림은 위쪽 학생 PK→수강 FK, 과목 PK→수강 FK의 소속부터 읽고 아래 실제 학번·과목코드를 대조한다. 그림의 1001 장정훈·90과 현재 예제의 1001 양지훈은 별도 데이터다. Chen의 타원·마름모와 까마귀발 기호를 섞어 해석하지 않는다.',marks=('소속','별도 데이터'))
 ],'관계의 다수 여부와 반드시 연결되어야 하는지는 다르다. 물리 구현에서는 연결표와 FK로 관계를 구현할 수 있지만 선 하나가 실제 제약 정의를 대신하지 않는다.')],
 [('학생 자체의 속성과 학생-과목의 짝을 저장하는 표를 구분하자.','수강표다. (1001,C01)처럼 학생과 과목의 연결 하나를 한 행으로 저장한다.'),('범위의 왼쪽 숫자가 최소인지 최대인지 생각해 보자.','0은 최소 연결 건수가 0이어도 된다는 뜻이다. N은 여러 건을 허용한다는 최대 대응 수다.'),('선의 끝과 숫자·원 표기가 없을 때 무엇을 알 수 있을까?','단순 선만으로 필수·선택과 정확한 대응 수를 항상 알 수 없다. 범례와 관계차수·최소 참여 표기를 함께 봐야 한다.')],
 [('수강의 학번은 학생의 학번이랑 같은 컬럼이야?','값으로 연결되지만 소속이 다른 별개 컬럼이다. 학생.학번은 학생 행을 구별하고 수강.학번은 어느 학생의 수강인지 가리킨다.'),('ERD는 어디부터 그려?','대상을 찾아 배치하고 관계를 연결한 뒤 관계명·최대 대응 수·필수 여부를 적는다. 학생·과목·수강의 의미를 먼저 정해야 선의 뜻도 정해진다.')],
 ['0..N은 이 해설에서 명시한 업무 규칙이다. 원본 표 몇 행만 보고 모든 시스템의 최소 참여수를 추정하지 않는다.'],sources=[MODEL])

lid='1-1-06'
lesson(lid,'학생이라는 종류와 1002번 양지훈 한 사람의 기록, 학과라는 항목을 따로 가리켜 보자.',
 '테이블을 실행하는 과정이 아니라 대상을 구분하는 연습이다. 표 제목·한 행 전체·열 제목의 세 위치를 비교한다.',(13,15),[
 example(lid,0,'설계 회의에서 학생 정보를 관리하자는 말과 양지훈의 학과를 고치자는 말을 구별해야 한다.','개념: 엔터티·인스턴스·속성의 범위를 구별한다.',
 ['학번·이름·학과 세 속성이 있는 학생표다. 유성재·양지훈·이승현의 세 행을 원본 그대로 읽는다.'],[
 step('표 제목은 관리 대상의 종류','학생은 공통적으로 학번·이름·학과를 관리할 대상의 종류다. 이승현이라는 이름 하나가 학생 엔터티 전체를 뜻하지는 않는다.',original(lid),marks=('학번·이름·학과',)),
 step('1002번의 한 행 전체','(1002, 양지훈, 전자)는 특정 학생 인스턴스 한 건이다. 양지훈이라는 이름만이 아니라 학번과 학과까지 묶어서 한 행이다. 같은 이름이 생겨도 학번으로 다른 학생인지 판단한다.',table('현재 보는 인스턴스',['학번','이름','학과'],[['1002','양지훈','전자']]),marks=('1002, 양지훈, 전자',),rows=(0,)),
 step('열 제목과 그 안의 값을 나누기','학과는 항목 이름인 속성이고 전자는 1002번 학생의 학과 속성값이다. 세 학생 모두 학과라는 항목을 공유하지만 그 값은 컴퓨터·전자·기계로 다를 수 있다.',result(lid),marks=('학과는 항목 이름','전자는 1002번 학생의 학과 속성값')),
 step('학생이 관리 대상이 되는 이유','학생별 성적·수강 업무에서 계속 참조하므로 학생 기록을 지속적으로 관리한다. 지금 세 행이 있다는 사실과 관리할 종류의 정의는 구별한다. 업무 시작 직후 한 행만 저장되어도 학생이라는 설계가 무효가 되지는 않는다.',table('분류의 기준',['질문','학생 예제의 답'],[['업무에 필요한가','수강·성적 관리에 필요'],['구별 가능한가','학번으로 구별'],['어떤 항목이 있나','학번·이름·학과']]),marks=('관리할 종류의 정의',)),
 step('기존 속성·튜플 그림과 대조','속성·튜플 그림은 이름 한 칸이 아니라 표시된 행의 모든 값을 묶는다. 그림에는 네 열이 있지만 현재 예제는 학번·이름·학과 세 열이다. 그림의 개수를 외워 답하지 말고 지금 표를 직접 센다.',marks=('현재 예제는 학번·이름·학과 세 열',))
 ],'유형·개념·사건은 대상의 성격, 기본·중심·행위는 발생 근원과 업무 역할이라는 서로 다른 분류 축이다. 주문 같은 대상은 업무에 따라 사건이면서 중심 엔터티로 분류될 수 있다.')],
 [('이름 말고 행을 구별하는 번호가 무엇인지 보자.','동명이인은 가능하다. 학번이 다르면 서로 다른 학생 인스턴스다. 이름 하나를 식별자로 정했다고 가정하면 안 된다.'),('사람 자체인지 업무가 일어나 남은 기록인지 생각해 보자.','수강신청은 업무 행위로 발생한 기록이라 사건 엔터티에 가깝다. 학생 자체라는 유형 엔터티와 구별한다.'),('현재 저장된 건수와 계속 관리할 종류의 정의를 나눠 보자.','한 건뿐이어도 설계가 무효인 것은 아니다. 여러 개별 사례를 관리할 종류라는 성격과 특정 시점의 행 수는 다르다.')],
 [('엔터티면 무조건 눈에 보여야 해?','아니다. 학생 같은 실체뿐 아니라 학과라는 개념, 수강신청이라는 사건도 관리 대상이 된다.'),('엔터티가 반드시 다른 표와 연결돼야 해?','보통 업무 관계를 가지지만 코드성·통계성·시스템 관리 대상 등 예외가 있다. 표 하나만 떨어져 있다고 즉시 잘못된 설계로 단정하지 않는다.')],
 ['PDF의 다수 인스턴스 설명은 여러 사례를 관리하는 대상의 성격이다. 현재 저장 건수가 무조건 두 건 이상이어야 한다는 제약으로 구현하지 않는다.'],sources=[MODEL])

lid='1-1-07'
lesson(lid,'학년값 4와 열 개수 4를 구별하고 현재 없는 값도 도메인에 포함될 수 있음을 확인하자.',
 '학생표의 열 제목·행·허용 규칙을 읽는 개념 학습이다. 학번·이름·학과·학년을 구체적으로 세고 한 행의 값과 구분한다.',(15,18),[
 example(lid,0,'표에서 차수와 카디널리티를 묻는 문제를 숫자 모양만 보고 풀지 않도록 한다.','개념: 속성·속성값·허용 범위·행과 열의 수를 판정한다.',
 ['원본의 학생표는 이승현·양지훈·박보성 세 학생과 학번·이름·학과·학년 네 열이다.','허용 규칙 예 표의 학년 1~4와 이름 필수 등은 설계 규칙 예시다. 실제 DDL이 실행된 상태로 단정하지 않는다.'],[
 step('항목 네 개를 하나씩 짚기','학번, 이름, 학과, 학년이라는 열 제목 네 개가 속성이다. 차수는 이 속성 개수인 4다. 첫 학생의 학년값 4를 보고 세는 것이 아니다.',original(lid),marks=('학번, 이름, 학과, 학년','차수')),
 step('행은 정보 묶음 전체','(1001, 이승현, 컴퓨터, 4), (1002, 양지훈, 전자, 3), (1003, 박보성, 컴퓨터, 2)가 각각 한 행이다. 정보 묶음 세 개이므로 카디널리티는 3이다.',original(lid),marks=('카디널리티는 3',),rows=(0,1,2)),
 step('허용된 값과 현재 들어 있는 값','학년에는 지금 2·3·4가 보인다. 허용 규칙을 1·2·3·4로 정했다면 현재 학생이 없어도 1은 허용된다. 반대로 표에 없다는 이유만으로 9를 넣어도 되는 것은 아니다.',table('학년 도메인 판정 · 설계 규칙 예',['입력값','현재 보이는가','1~4 규칙 판정'],[['1','아니오','허용'],['4','예','허용'],['9','아니오','거부']]),marks=('현재 학생이 없어도 1은 허용','9')),
 step('다른 분류 축을 구별하기','이름은 업무에서 수집하는 기본속성이다. 다른 값으로 계산하는 금액은 파생속성이고 설계 편의를 위해 만든 관리 번호는 설계속성일 수 있다. 현재 학생표에는 수량·단가·금액이 없으므로 별도 개념 예로만 비교한다.',result(lid),marks=('별도 개념 예',)),
 step('그림에서는 열 제목과 테두리 행','기존 그림의 학번·이름·학과·학년 화살표는 속성을, 테두리는 한 튜플 전체를 가리킨다. 그 그림의 노우성 행과 현재 양지훈 행을 섞지 않는다. 학년의 4와 차수 4가 우연히 같아도 세는 대상이 다르다.',marks=('한 튜플 전체','세는 대상이 다르다'))
 ],'속성은 학년이라는 항목, 속성값은 이승현 행의 4, 도메인은 넣어도 되는 1~4의 범위다. 이 세 가지를 하나의 숫자로 뭉뚱그리지 않는다.')],
 [('맨 위 열 제목을 소리 내어 한 번씩 세어 보자.','학번·이름·학과·학년 네 항목이라 차수는 4다. 학생 세 명이라는 행 수와 구별한다.'),('현재 관측된 값만 허용 규칙의 전부인가?','아니다. 규칙이 1~4이면 지금 1학년 학생이 없어도 1은 허용 범위에 포함된다.'),('값을 직접 수집했는지 다른 항목에서 계산했는지 보자.','수량과 단가를 곱해 얻는 금액은 파생속성이다. 현재 학생표 계산이 아니라 확인문제에서 제시한 별도 계산 예다.')],
 [('이승현은 속성이야?','이름이라는 열이 속성이고 이승현은 그 열에 저장된 속성값이다.'),('주소는 무조건 원자값이 아니야?','업무에서 어떤 하나의 값으로 다루는지에 따라 판단한다. 이름이나 날짜도 글자·연월일로 나눌 수 있다는 이유만으로 무조건 1NF 위반이 되는 것은 아니다.')],
 ['PDF 17쪽 원자성 문항은 업무에서 이름·날짜를 어떻게 다루는지 조건이 충분하지 않아 보충 주의가 필요하다. 날짜만 항상 원자값이고 이름은 항상 비원자값이라는 규칙으로 확장하지 않는다.','도메인의 정수형이 반드시 양수만 허용한다는 뜻은 아니다. 1~4처럼 실제 업무 제한을 따로 정한다.'],sources=[NORMAL])

lid='1-1-08'
lesson(lid,'같은 D01이 학과표에는 한 번, 학생표에는 두 번 있어도 되는 이유와 FK의 소속을 설명하자.',
 '학과 한 곳과 여러 학생의 관계를 해석한다. 학과.학과코드와 학생.학과코드는 이름이 같아도 서로 다른 표의 컬럼이다.',(18,22),[
 example(lid,0,'양지훈과 양선규가 모두 컴퓨터 학과에 소속되어도 중복 학생으로 오해하지 않는다.','개념: 학과 1:N 학생 연결과 외래키 소속을 확인한다.',
 ['원본에서 학과 D01=컴퓨터, D02=전자이며 학생은 학번으로 구별한다.','학생.학과코드가 학과.학과코드를 참조한다는 관계를 전제로 한다. 삭제 옵션·NULL 허용 여부는 이 표만으로 확정할 수 없다.'],[
 step('부모의 D01을 먼저 찾기','학과표의 D01은 컴퓨터 학과 한 곳을 구별한다. 이 값에 대응하는 학과명은 컴퓨터다. 학생표의 학번 1001처럼 사람을 구별하는 번호와 다른 역할이다.',original(lid,0,0),marks=('학과표의 D01',),rows=(0,)),
 step('자식의 어느 열이 참조하는가','학생.학과코드가 참조하는 쪽인 FK다. 양지훈 1001의 D01, 양선규 1002의 D01을 학과표 D01과 각각 맞춘다. 학생.학번 1001과 1002는 달라 두 학생이며 FK D01의 반복은 이 1:N 설계에서 허용된다.',original(lid,0,1),marks=('학생.학과코드','FK D01의 반복'),rows=(0,1)),
 step('세 번째 연결도 같은 방식','유성재 1003의 학과코드 D02는 전자 학과와 연결된다. 이름이 같은 열끼리 무조건 연결한 것이 아니라 이 관계의 참조 규칙에 따라 학과코드 값을 비교한 것이다.',table('학습용 참조 확인',['학생.학번','학생.이름','학생.학과코드','학과.학과명'],[['1001','양지훈','D01','컴퓨터'],['1002','양선규','D01','컴퓨터'],['1003','유성재','D02','전자']]),marks=('D02','전자'),rows=(2,)),
 step('한 쪽에서 한 개를 고정해 세기','학과 D01 한 곳에서 보면 양지훈과 양선규 두 학생이 연결된다. 학생 양지훈 한 명에서 보면 이 예제에서는 학과 하나 D01이다. 연결 결과의 학생 목록은 설명용 묶음이지 학생표의 이름 칸에 쉼표 목록을 새로 저장한 것이 아니다.',result(lid),marks=('학과 D01 한 곳','학과 하나 D01')),
 step('그림의 차수와 필수 여부를 따로','기존 관계 그림에서 학과에서 학생으로 갈라지는 선의 양 끝을 보고, ERD에서는 0 또는 1 같은 최소 참여 표시를 따로 본다. 비식별 관계인지 여부는 FK가 자식 PK에 포함되는지로 판단한다. 자식 FK가 필수인지와 부모 삭제 시 동작은 별도 규칙이다.',table('서로 다른 판단 축',['질문','확인할 것'],[['1:N인가','한 인스턴스에 연결될 최대 수'],['선택·필수인가','최소 참여수 또는 NOT NULL'],['식별 관계인가','FK가 자식 주식별자에 포함되는가'],['삭제가 전파되는가','정의된 삭제 동작']]),marks=('별도 규칙',))
 ],'부모 키의 유일성과 자식 FK의 반복 가능성을 구분한다. FK에도 별도 UNIQUE를 걸면 관계 제약이 달라질 수 있으므로 모든 FK가 어떤 상황에서든 중복 가능하다고 외우지 않는다.')],
 [('두 학생을 구별하는 열과 소속을 가리키는 열이 같은가?','이 예제는 학번으로 양지훈과 양선규를 구별하고 학과코드 D01로 같은 학과를 가리킨다. FK 반복은 정상이다.'),('연결된 부모의 값이 자식의 대표 식별 기준 안에 들어가는지 보자.','부모 키가 자식 PK의 일부가 되면 식별 관계다. 부모 삭제 시 CASCADE가 자동이라는 뜻은 아니다.'),('N이 최대 대응 수인지 최소 참여수인지 생각해 보자.','1:N만으로 최소 한 건을 요구하는지 알 수 없다. 학과에 학생이 0명이어도 되는지는 0..N/1..N 같은 최소 참여 규칙을 확인해야 한다.')],
 [('어느 학과코드가 외래키야?','이 예제에서는 학생표 안의 학생.학과코드다. 학과표의 학과.학과코드는 참조받는 키다. 같은 글자라도 소속이 다르다.'),('비식별 관계면 NULL은 항상 돼?','아니다. 자식의 FK가 PK 밖에 있다는 말일 뿐이다. FK에 NOT NULL을 지정하거나 필수 참여 규칙을 두면 부모 연결이 필요하다.'),('식별 관계면 부모 삭제할 때 자식도 자동 삭제돼?','그 사실만으로 자동 삭제되지 않는다. Oracle에서는 ON DELETE CASCADE 등 실제 제약 정의를 확인해야 한다.')],
 ['PDF 18~20쪽의 존재·행위 관계와 UML 연관·의존의 실선·점선을 ERD 식별·비식별의 표시와 같은 기준으로 합치지 않는다.','PDF 22쪽에서 FK가 있다는 사실만으로 필수 참여가 증명되지는 않는다. 해당 ERD의 최소 참여 표시와 컬럼 제약을 함께 읽는다.'],
 notes=['PDF 1-1 25~27쪽에서 비식별 관계의 독립 존재 및 식별 관계의 삭제 전파를 일반화하는 표현을 별도 주의로 연결했다. 원문·정답은 바꾸지 않았다.'],sources=[CONSTRAINT,MODEL])

lid='1-1-09'
lesson(lid,'한창주의 DB 점수와 JAVA 점수를 구별할 때 필요한 최소 항목을 찾아보자.',
 '수강 한 행을 유일하게 지정할 속성 조합을 정한다. 학번과 과목코드를 함께 쓰는 것은 한 기본키를 두 컬럼으로 구성하는 뜻이다.',(23,27),[
 example(lid,0,'점수를 수정할 때 한창주의 두 수강 중 어느 과목인지 빠뜨리지 않기 위한 설계다.','개념: 수강의 복합 식별자와 최소성을 판정한다.',
 ['원문은 한 학기 안에서 같은 학생이 같은 과목을 한 번만 수강한다고 전제한다.','이름 열은 원본 그대로 유지하지만 연결·식별 판단은 학번과 과목코드로 한다.'],[
 step('학번만 지정하면 두 행','학번 1001을 고르면 한창주의 C01 90점과 C02 80점이 함께 나온다. 학생 한 명은 구별해도 수강 한 건은 못 고른다.',table('학번만으로 찾은 수강',['학번','과목코드','이름','점수'],[['1001','C01','한창주','90'],['1001','C02','한창주','80']]),marks=('수강 한 건은 못 고른다',)),
 step('과목코드만 지정해도 두 행','과목코드 C01을 고르면 1001 한창주 90점과 1002 양지훈 70점이 함께 나온다. C01이라는 과목은 구별해도 어느 학생의 수강인지는 부족하다.',table('과목코드만으로 찾은 수강',['학번','과목코드','이름','점수'],[['1001','C01','한창주','90'],['1002','C01','양지훈','70']]),marks=('어느 학생의 수강',)),
 step('두 값을 함께 지정하면 한 행','(1001,C01)은 한창주의 C01 90점만 지정한다. (1001,C02), (1002,C01)도 각각 다른 조합이다. 어느 한 항목을 빼면 앞 단계처럼 중복되므로 이 업무 규칙에서 두 항목이 모두 필요하다.',result(lid),marks=('1001,C01','두 항목이 모두 필요')),
 step('PK 한 개와 컬럼 두 개','학번+과목코드는 문자열 덧셈이 아니라 두 속성의 조합이라는 표시다. 기본키를 이 조합으로 정하면 기본키 제약 하나가 두 컬럼을 포함한다. 두 컬럼이 각각 단독으로 유일해야 한다는 뜻이 아니다.',table('식별 범위',['대상','식별 기준','뜻'],[['학생 한 명','학번','1001 한창주'],['이 학기 수강 한 건','학번 + 과목코드','1001의 C01 수강']]),marks=('기본키 제약 하나','두 컬럼')),
 step('시간 범위가 바뀌면 재검토','여러 학기의 이력을 함께 보관하면 한창주가 다음 학기에 C01을 다시 들을 수 있다. 그 경우 (1001,C01)이 두 건이 될 수 있어 학기 등 추가 기준이 필요하다. 현재 예제에 학기 컬럼이 이미 있는 것으로 표시하지 않는다.',marks=('학기 등 추가 기준','현재 예제'))
 ],'유일성은 서로 다른 행을 구별하는가, 최소성은 항목을 덜 써도 가능한가라는 별도 검사다. 장래 업무 규칙 없이 현재 세 조합이 우연히 다르다는 이유만으로 키를 확정하지 않는다.')],
 [('이름을 빼도 같은 한 사람을 고를 수 있는지 보자.','학번만 유일하다는 전제라면 이름은 식별에 불필요하다. (학번,이름)은 슈퍼키일 수 있어도 최소성을 만족하지 않는다.'),('주식별자로 행을 반드시 가리킬 수 있어야 한다는 조건을 떠올리자.','주식별자는 NULL을 허용하지 않는다. 복합 주식별자라면 구성 속성 모두 빠짐없이 있어야 한다.'),('현재 한 학기라는 전제가 유지되는지 확인하자.','여러 학기라면 같은 학생·과목 조합이 반복될 수 있다. 학기 등 추가 식별 기준을 검토해야 한다. 기존 예제의 두 컬럼 규칙을 무조건 유지하면 다른 수강 이력이 섞인다.')],
 [('기본키가 두 개인 거야?','기본키 제약은 하나이고 구성 컬럼이 둘이다. 학번 1001도 과목코드 C01도 단독으로는 수강표에서 반복될 수 있다.'),('인조번호만 붙이면 업무 중복도 없어져?','아니다. 새 번호가 달라도 같은 학기·학생·과목의 수강을 중복 등록할 수 있다. 업무 조합의 UNIQUE 같은 별도 규칙이 필요하다.')],
 ['불변성은 식별자가 자주 바뀌지 않도록 선택하는 원칙이다. DB가 모든 PK 변경을 문법적으로 무조건 금지한다는 뜻은 아니다.'],sources=[CONSTRAINT,MODEL])

lid='1-2-01'
lesson(lid,'양선규부터 유성재까지 네 학생의 정보 묶음과 학번·이름·학과 세 항목을 따로 세어 보자.',
 '릴레이션 구조와 현재 저장값을 구별하는 개념이다. 수학적 관계 모델의 성질을 SQL 조회 결과의 중복·정렬 규칙과 혼동하지 않는다.',(1,3),[
 example(lid,0,'차수와 카디널리티를 행·열의 실제 이름에 연결해 정확히 판정한다.','개념: 학생 릴레이션의 구조와 현재 인스턴스를 읽는다.',
 ['현재 학생표는 학번·이름·학과 세 열과 1001 양선규,1002 박상현,1003 양지훈,1004 유성재의 네 행이다.'],[
 step('구조는 항목 이름으로 세기','학번·이름·학과는 세 속성이다. 차수는 3이다. 각 열 아래 값이 네 개씩 있다고 차수가 4가 되지는 않는다.',original(lid),marks=('학번·이름·학과','차수는 3')),
 step('실제 행 네 묶음','(1001,양선규,컴퓨터), (1002,박상현,전자), (1003,양지훈,컴퓨터), (1004,유성재,기계)가 네 튜플이다. 행 제목을 빼고 세므로 카디널리티는 4다.',original(lid),marks=('카디널리티는 4',)),
 step('같은 학과값과 중복 튜플','1001과 1003의 학과는 모두 컴퓨터지만 학번과 이름이 다르다. 한 컬럼값이 같은 것과 행 전체가 같은 것은 다르므로 서로 다른 튜플이다.',table('두 튜플 비교',['항목','1001번','1003번','비교'],[['학번','1001','1003','다름'],['이름','양선규','양지훈','다름'],['학과','컴퓨터','컴퓨터','같음']]),marks=('학번과 이름이 다르다',)),
 step('바뀌는 대상이 행인지 열인지','추가 가정: 동일 구조에 학생 한 명을 더 넣으면 행이 4→5가 되지만 차수 3은 유지된다. 나이 열을 구조에 추가하면 차수 3→4가 되지만 기존 네 학생 행은 유지된다. 두 가정은 각각 독립된 변경이다.',table('독립적인 변경 가정',['작업','차수','카디널리티'],[['현재 원본','3','4'],['학생 한 명 추가','3 · 유지','5 · 변경'],['나이 열 추가','4 · 변경','4 · 유지']]),marks=('각각 독립된 변경',))
 ],'관계 모델의 튜플은 순서 없는 집합이다. 실제 SQL SELECT는 DISTINCT가 없으면 중복을 남길 수 있고 ORDER BY가 없으면 출력 행 순서를 보장하지 않는다.')],
 [('표의 항목 이름이 추가되는지 학생 기록이 추가되는지 확인하자.','같은 세 열에 학생 한 행이 더 생기므로 카디널리티가 4에서 5로 바뀐다. 차수는 3으로 유지된다.'),('나이는 새로운 학생인가 새로운 항목인가?','나이라는 새 속성이므로 차수가 3에서 4로 바뀐다. 네 학생의 행 수는 그대로다.'),('컴퓨터 한 값만 보지 말고 학번·이름까지 비교하자.','1001 양선규와 1003 양지훈은 학과만 같고 행 전체는 다르다. 따라서 중복 튜플이 아니다.')],
 [('릴레이션이 표의 관계선이야?','여기서 relation은 학번·이름·학과로 구성된 학생 표를 말한다. ERD에서 엔터티끼리 연결한 relationship과 문맥을 구별한다.'),('그림에서 카디널리티 3이던데?','기존 속성 그림은 세 학생·네 열이고 이 예제는 네 학생·세 열이다. 그림의 답을 옮기지 말고 현재 표의 행과 열을 다시 센다.')],
 ['도메인에 NULL 허용 여부를 설명할 수 있지만 NULL은 일반 문자열이나 숫자 0과 같은 값으로 다루지 않는다.'],sources=[INTRO])

lid='1-2-02'
lesson(lid,'학번과 이메일이 각각 고유할 때 대표 키와 다른 후보, 불필요하게 큰 조합을 구별하자.',
 '키 분류를 확인하는 설계 예제다. 테이블을 만들거나 열을 복사하지 않는다. 유일성·최소성·선택 여부를 차례로 검사한다.',(3,6),[
 example(lid,0,'학생을 찾는 기준이 학번과 이메일 두 가지일 때 어떤 용어를 붙일지 결정한다.','개념: 슈퍼키·후보키·기본키·대체키·외래키를 구별한다.',
 ['학번과 이메일은 필수이며 각각 고유하다는 업무 규칙이 원문에 있다. 현재 값이 우연히 다르다는 관찰만으로 키로 정한 것이 아니다.','기본키는 학번으로 선택한다. 학과코드는 학과표를 참조한다고 결과에 제시되어 있지만 학과표 실제 행은 원본에 없다.'],[
 step('학번으로 한 행씩 구별','학번 1001은 박강열,1002는 이승현,1003은 한창주 한 행씩 지정한다. 학번이 필수·고유라는 업무 규칙이 있으므로 학생을 유일하게 구별한다.',original(lid),marks=('학번 1001','필수·고유')),
 step('이메일도 독립적인 후보','s1@example.test는 박강열, s2@example.test는 이승현, s3@example.test는 한창주를 가리킨다. 이메일도 필수·고유이고 하나의 항목만으로 충분하므로 학번과 나란히 후보키다.',table('별도의 식별 기준',['학생','학번으로 조회','이메일로 조회'],[['박강열','1001','s1@example.test'],['이승현','1002','s2@example.test'],['한창주','1003','s3@example.test']]),marks=('이메일도 필수·고유',)),
 step('대표 선택은 다른 후보를 없애지 않는다','학번을 대표로 선택하면 학번은 기본키이고 이메일은 대체키다. 두 항목은 여전히 후보키와 슈퍼키에도 속한다. 대체키가 됐다고 이메일의 고유 규칙을 삭제한 것이 아니다.',result(lid),marks=('학번은 기본키','이메일은 대체키')),
 step('최소성은 하나 빼서 확인','(학번,이름)에서 이름을 빼도 학번만으로 박강열을 구별한다. 따라서 이 조합은 유일성은 만족해 슈퍼키지만 최소성이 없어 후보키가 아니다. 반면 학과코드 D01은 두 학생에게 있어 학생 식별용 키가 아니다.',table('키 검사',['속성 집합','유일성','최소성','판정'],[['학번','충족','충족','후보키 · 기본키'],['이메일','충족','충족','후보키 · 대체키'],['학번+이름','충족','실패','슈퍼키만'],['학과코드','실패','검사 대상 아님','학생 식별 불가']]),marks=('최소성이 없어 후보키가 아니다',)),
 step('외래키의 다른 역할','학생.학과코드는 학생 한 명을 구별하기 위한 것이 아니라 어느 학과인지 가리키는 참조다. 기존 PK/FK 그림처럼 자식 쪽 참조값이 반복될 수 있다. 다만 현재 원본에 학과표가 없으므로 D01·D02가 부모에 실제 존재하는지까지 실행 검증했다고 말하지 않는다.',marks=('어느 학과인지','학생.학과코드'))
 ],'고유하면서 필수인 이메일이라는 원문 조건이 중요하다. UNIQUE만 있고 NULL이 가능하다면 이 문항의 필수 후보키 전제와 같다고 단정하지 않는다.')],
 [('후보키의 조건에서 유일성이 빠지는지 확인하자.','후보키는 유일성을 만족하는 슈퍼키 중 최소성까지 갖춘 것이다. 그래서 모든 후보키는 슈퍼키에 포함된다.'),('대표로 선택된 후보와 선택되지 않은 후보를 구별하자.','대표 학번은 기본키이고 선택되지 않은 필수·고유 이메일은 대체키다. 이메일도 후보키라는 성질은 유지된다.'),('참조 대상에 필요한 것은 참조 가능한 유일한 키인가, 명칭 PK뿐인가?','SQL의 FK는 참조 가능한 PK 또는 UNIQUE 키를 대상으로 할 수 있다. 부모의 보통 열이나 단지 현재 값이 다른 열을 아무 조건 없이 참조하는 것은 아니다.')],
 [('학과코드는 이름이 KEY가 아닌데 왜 FK야?','문자 이름으로 자동 결정되지 않는다. 어느 표의 키를 참조하도록 정의했는지가 역할을 정한다.'),('PK 하나라는 말은 컬럼도 하나야?','아니다. 이 예제는 학번 한 컬럼이지만 수강에서는 학번·과목코드처럼 여러 컬럼을 묶어 기본키 하나로 만들 수 있다.')],
 ['원본 키 분류표의 학과코드 FK는 관계 전제다. 빠진 학과 원본표를 사실인 것처럼 생성하지 않았다.','FK는 자기 테이블의 키를 참조하는 자기참조일 수도 있다. 다른 표만 가능하다고 절대화하지 않는다.'],sources=[CONSTRAINT])

lid='1-2-03'
lesson(lid,'입력하려는 행을 기존학생과 학과표에 대조해 정확히 어느 컬럼이 규칙을 어겼는지 말하자.',
 '새 테이블을 만드는 코드가 아니라 네 입력 후보를 독립적으로 판정하는 개념 예제다. 거부된 후보는 정상 저장된 학생표에 넣지 않는다.',(7,11),[
 example(lid,0,'새 학생을 등록하기 전에 중복 학번·허용 밖 학년·없는 학과를 걸러야 한다.','개념: 입력 시도의 PK·NOT NULL·범위·FK 규칙을 판정한다.',
 ['학과 D01=컴퓨터,D02=전자가 있다. 기존학생은 (1001,박강열,2,D01) 한 행이다.','입력후보 네 행은 각각 같은 초기 상태에서 독립적으로 시도한다. 원문에 이름 NOT NULL,학년1~4,학과코드FK 규칙이 있다.','학과코드의 NULL 여부나 부모 삭제 정책은 이 예제의 네 후보에 드러나지 않으므로 별도 조건을 확인해야 한다.'],[
 step('규칙을 어느 표의 열에 붙였는지','기존학생.학번은 PK이고 기존학생.이름은 필수다. 학년은 1~4 범위, 학생의 학과코드는 부모 학과.학과코드를 참조한다. 학과에 D01이 있다는 사실을 학생의 학번 1001 중복 허용과 혼동하지 않는다.',table('검사 대상',['학생 쪽 열','확인할 규칙','대조 위치'],[['학번','중복·NULL 금지','기존학생.학번'],['이름','NULL 금지','입력후보.이름'],['학년','1~4','입력후보.학년'],['학과코드','유효한 부모 참조','학과.학과코드']]),marks=('기존학생.학번','학과.학과코드')),
 step('1001번 박보성의 입력 시도','기존 박강열의 학번이 1001인데 박보성도 1001을 요청했다. 이름은 달라도 PK인 학번이 같으므로 거부다. 기존 박강열을 박보성으로 덮어쓰는 UPDATE가 아니다.',table('입력 시도 · 저장되지 않음',['학번','이름','학년','학과코드','판정'],[['1001','박보성','3','D01','거부 · PK 중복']]),marks=('PK인 학번이 같으므로 거부',)),
 step('1002번 김현수의 학년 대입','학번 1002는 새 번호이고 D02도 부모에 있다. 하지만 학년 9는 1~4 밖이므로 거부다. 이름 김현수 때문이 아니라 학년 컬럼의 허용 범위를 어긴 것이다.',table('입력 시도 · 저장되지 않음',['학번','이름','학년','학과코드','판정'],[['1002','김현수','9','D02','거부 · 9는 1~4 밖']]),marks=('학년 9','학년 컬럼')), 
 step('1003번 양선규의 참조 방향','학생 쪽 D99를 부모 학과표의 D01·D02와 비교하면 일치하는 코드가 없다. 따라서 거부다. 학생 입력이 D99 학과를 자동으로 만드는 것은 아니다.',table('입력 시도 · 저장되지 않음',['학번','이름','학년','학과코드','판정'],[['1003','양선규','1','D99','거부 · 부모 D99 없음']]),marks=('학생 쪽 D99','부모 학과표')),
 step('1004번 유성재는 모두 통과','학번 1004는 기존 1001과 다르고 이름 유성재가 있다. 학년 4는 허용 범위이고 학과 D02도 존재하므로 허용한다. 이 독립 시도가 성공한 상태라면 기존 박강열은 유지되고 유성재 한 행만 추가된다.',table('허용된 독립 시도의 저장 상태',['학번','이름','학년','학과코드','변화'],[['1001','박강열','2','D01','유지'],['1004','유성재','4','D02','추가']]),marks=('유성재 한 행만 추가',)),
 step('그림과 원본의 기준을 분리','기존 무결성 그림도 기준표 → 입력 시도 → 거부 이유 순으로 읽는다. 그림의 학번1·D01만 있는 학과표와 현재 학번1001·D01/D02 표는 다르다. 현재 네 후보 판정은 이 원본의 실제 값으로 한다.',result(lid),marks=('이 원본의 실제 값',))
 ],'PK는 행 식별, FK는 참조 대상, CHECK는 조건, NOT NULL은 값의 부재를 제한한다. CHECK(점수>=0)에서 NULL 비교는 알 수 없음이고 FALSE와 다르므로 NULL까지 금지하려면 NOT NULL을 따로 확인한다.')],
 [('입력값 D99를 어느 부모 컬럼에서 찾아야 하는지 보자.','학생.학과코드가 참조하는 학과.학과코드에는 D01·D02만 있다. D99가 없으므로 참조 무결성 위반이다.'),('NULL>=0을 참 또는 거짓으로 단정할 수 있는가?','NULL>=0은 UNKNOWN이다. Oracle CHECK는 FALSE를 거부하고 UNKNOWN은 통과할 수 있으므로 CHECK만으로 NULL을 막지 못한다. NOT NULL은 별도다.'),('중복된 값이 행 식별자인지 참조값인지 먼저 보자.','기본키 중복은 개체 무결성 위반이다. 1001 박보성은 기존 1001 박강열과 학번이 같아 학생 한 명을 유일하게 구별할 수 없게 한다.')],
 [('DEFAULT면 NULL을 넣어도 기본값이야?','일반 DEFAULT는 컬럼 생략이나 DEFAULT 키워드 요청 때 적용할 수 있지만 명시적 NULL을 자동으로 기본값으로 바꾸는 것은 아니다. DEFAULT ON NULL은 별도 문법이다.'),('이름 필수면 동명이인도 금지야?','아니다. NOT NULL은 값을 넣으라는 규칙이고 UNIQUE는 중복을 제한한다. 이 원본에는 이름 UNIQUE가 없다.'),('FK는 NULL을 절대 못 넣어?','FK 자체와 NOT NULL은 다른 규칙이다. NULL 허용 여부는 해당 컬럼의 필수 제약을 확인한다. 이 네 입력후보에는 학과코드 NULL이 없다.'),('입력 후보 네 명이 최종 학생표야?','아니다. 후보는 시도이고 세 후보는 거부된다. 각 시도는 원래 박강열 한 행에서 독립적으로 검사한다.')],
 ['Oracle에서 부모 삭제 옵션은 ON DELETE CASCADE/SET NULL 등 실제 지원 문법을 확인한다. PDF의 ON UPDATE·SET DEFAULT 옵션 나열을 Oracle 문법으로 그대로 실행하면 안 된다.','NULL은 공백 문자와 다르다. 화면 입력칸을 클릭했는지가 아니라 DB에 전달한 값과 DBMS의 처리 규칙이 중요하다.'],
 notes=['PDF 1-2 10쪽 입사일·퇴사일 선후 문구는 일반적인 업무 규칙과 반대 방향으로 읽힐 수 있다. 해당 원문 보기를 앱의 정상 업무 규칙으로 새로 채택하지 않았다.','DEFAULT는 허용 범위 위반 값을 거부하는 CHECK와 역할이 다르다. PDF의 제약 분류 용어는 보존하되 실제 역할은 분리해 설명한다.'],sources=[CONSTRAINT])

lid='1-2-04'
lesson(lid,'표를 만드는 일, 학생을 넣는 일, 조회 권한을 주는 일, 변경을 확정하는 일을 구분하자.',
 '네 요구를 명령 종류로 분류하는 예제다. 나열된 단어는 기능 이름이며 완전한 SQL 실행문이나 순서대로 실행한 결과가 아니다.',(11,14),[
 example(lid,0,'사용자가 무엇을 원하는지 듣고 필요한 SQL의 종류부터 찾는다.','개념: 구조·데이터·권한·트랜잭션이라는 작업 종류를 구별한다.',
 ['원본은 요구 네 개를 분류하는 표다. 실제 CREATE TABLE 정의·INSERT 값·사용자명·트랜잭션 상태는 주어지지 않았다.','각 요구는 독립적으로 분류하며 임의의 실행 후 학생표를 만들어 결과라고 제시하지 않는다.'],[
 step('학생표 틀을 만드는 요구','학생표의 구조를 만든다는 말은 어떤 컬럼에 어떤 값을 저장할지 정의한다는 뜻이다. CREATE는 만들다, TABLE은 표다. CREATE TABLE은 DDL이며 이 말만으로 새 학생 한 행이 입력되지는 않는다.',table('작업 분류',['요구','대상','분류'],[['학생표 구조 생성','테이블 정의','DDL']]),marks=('새 학생 한 행이 입력되지는 않는다',)),
 step('이미 있는 표에 학생 등록','학생 한 명을 등록한다면 이미 정의된 학생표에 새 행을 넣는 INSERT다. INSERT는 삽입이라는 뜻이고 DML에 속한다. 표 이름이나 컬럼 종류를 새로 만드는 작업과 다르다.',table('작업 분류',['요구','대상','분류'],[['학생 등록','테이블 안의 행','DML']]),marks=('새 행을 넣는 INSERT',)),
 step('누가 조회할 수 있는지 정하기','GRANT는 권한을 주다라는 뜻이다. 다른 계정에 조회 권한을 주어도 학생 행이나 점수는 그대로다. 데이터에 접근할 수 있는 권한을 바꾸는 DCL이다.',table('작업 분류',['요구','바뀌는 것','분류'],[['조회 권한 부여','계정의 접근 권한','DCL']]),marks=('학생 행이나 점수는 그대로',)),
 step('이미 한 변경을 확정하기','COMMIT은 현재 트랜잭션의 변경을 확정한다. 점수 80을 90으로 지정하는 일 자체는 UPDATE가 하고 COMMIT은 그 변경을 확정하는 TCL이다. 방금 바꾼 한 칸만 선택적으로 확정하는 명령이라고 생각하지 않는다.',result(lid),marks=('그 변경을 확정하는 TCL',)),
 step('행위 이름만으로 헷갈리지 않기','DELETE는 조건에 맞는 행을 지우는 DML, DROP은 객체를 없애는 DDL, TRUNCATE는 구조를 유지하면서 모든 행을 비우는 DDL이다. DDL이 구조만 다루어 데이터를 절대로 건드리지 않는다고 외우면 TRUNCATE에서 막힌다.',table('삭제 관련 비교',['명령','대상','이 강의 분류'],[['DELETE','선택한 데이터 행','DML'],['TRUNCATE','전체 데이터 행 · 구조 유지','DDL'],['DROP','테이블 객체','DDL']]),marks=('TRUNCATE','구조를 유지'))
 ],'분류와 트랜잭션 동작을 분리한다. Oracle DDL의 암묵적 COMMIT을 모든 DBMS의 공통 동작으로 일반화하지 않는다. SELECT를 DQL로 따로 부르는 자료도 있으므로 문항의 분류 기준을 따른다.')],
 [('학생이 새로 들어오는가, 기록할 항목이 새로 생기는가?','연락처 열을 추가하는 것은 학생표 구조 변경이므로 DDL이다. 기존 학생의 연락처 값을 입력하는 DML과 다르다.'),('점수 컬럼 자체를 만들었는지 안의 값만 바꾸는지 보자.','80→90은 기존 행의 점수 값을 수정하므로 DML이다. 컬럼 자료형을 바꾸는 ALTER와 다르다.'),('권한과 데이터 값을 구분해 보자.','GRANT는 계정에 권한을 부여한다. 새 학생 입력 INSERT나 구조 생성 CREATE가 아니다.')],
 [('COMMIT이 점수를 바꾸는 코드야?','점수를 바꾸는 값과 행은 UPDATE가 정한다. COMMIT은 현재 트랜잭션에서 이미 한 변경을 확정한다.'),('DDL은 항상 어느 DB든 롤백이 안 돼?','아니다. Oracle의 암묵적 커밋 특성을 다른 DBMS에 그대로 적용하지 않는다. 제품·명령·트랜잭션 설정을 확인한다.')],
 ['PDF 11~14쪽의 DDL 자동 COMMIT 설명을 제품 공통 규칙으로 확장하지 않는다. Oracle 문맥에 한정하고 다른 제품은 별도 확인한다.'],
 [term('DDL','분류 약어','Data Definition Language · 데이터 정의어','학생표라는 구조와 객체를 정의·변경한다.'),term('DML','분류 약어','Data Manipulation Language · 데이터 조작어','학생표의 행을 조회하거나 입력·수정·삭제한다.'),term('DCL','분류 약어','Data Control Language · 데이터 제어어','계정의 접근 권한을 부여·회수한다.'),term('TCL','분류 약어','Transaction Control Language · 트랜잭션 제어어','현재 변경의 확정·취소·중간 지점을 다룬다.')],sources=[COMMIT])

lid='1-2-05'
lesson(lid,'같은 C01 강의실을 두 군데에 저장했을 때 왜 한 줄만 바꾸면 문제가 되는지 확인하자.',
 'SQL 실행 예제가 아니라 저장 구조와 이상 현상을 비교한다. 정규화로 표를 나누는 일과 강의실 값을 301→401로 수정하는 일은 서로 다른 변화다.',(15,19),[
 example(lid,0,'DB 강의실이 301에서 401로 옮겨졌을 때 박보성과 유성재에게 서로 다른 방을 안내하지 않도록 한다.','개념: 중복 사실의 갱신 이상을 확인하고 사실별로 분리한다.',
 ['과목코드가 과목명과 강의실을 결정한다는 업무 규칙이 주어졌다. C01 DB의 강의실이 두 수강 행에 301로 반복된다.','학생표 분리는 학번이 학생 이름을 결정한다는 추가 전제로 해석한다. 현재 표만 보고 동명이인 금지나 이름→학번을 추정하지 않는다.','원본 결과의 C01 강의실은 401이다. 이는 표 분해에 더해 강의실 변경까지 반영한 상태이며 정규화 자체가 301을 401로 계산한 것이 아니다.'],[
 step('반복된 사실을 두 행에서 찾기','1001 박보성 C01 DB 301, 1002 유성재 C01 DB 301 두 행에 같은 과목의 같은 방이 반복된다. 서로 다른 학생이 같은 과목을 듣는 사실 자체는 정상이고 과목 사실을 두 군데서 관리하는 점이 수정 부담이다.',original(lid),marks=('같은 과목의 같은 방',),rows=(0,1)),
 step('한 행만 고쳤을 때의 불일치','가상 변경 시도: 박보성 행만 301→401로 바꾸고 유성재 행을 301에 남겨 두면 같은 C01의 방이 둘로 갈린다. 이 표는 오류 상태를 설명한 중간표이며 올바른 최종 결과가 아니다.',table('잘못된 갱신 시도 · 최종 정상표 아님',['학번','이름','과목코드','강의실','판정'],[['1001','박보성','C01','401','변경 · C01 값 불일치'],['1002','유성재','C01','301','유지 · C01 값 불일치'],['1003','박강열','C02','202','유지']]),marks=('같은 C01의 방이 둘로 갈린다',)),
 step('과목 사실을 한 곳에서 관리','과목표에 C01 DB 401, C02 JAVA 202를 한 번씩 둔다. C01의 방을 변경하면 이 한 사실을 참조하는 두 수강 모두 같은 최신 방으로 해석할 수 있다. C02의 JAVA 202는 바꿀 이유가 없어 유지된다.',result(lid,0,1),marks=('C02의 JAVA 202','유지')),
 step('학생 사실과 수강 연결은 보존','학생표에는 1001 박보성·1002 유성재·1003 박강열을, 수강표에는 (1001,C01),(1002,C01),(1003,C02)를 둔다. 수강 세 건을 지운 것이 아니다. 수강의 학번과 과목코드를 따라가면 누가 어떤 과목을 어디서 듣는지 다시 연결된다.',result(lid,0,2),marks=('수강 세 건을 지운 것이 아니다',)),
 step('연결해서 정보가 남는지 확인','분리 후 1001→박보성과 C01→DB·401을 연결하면 박보성의 DB 수강 사실이 나온다. 1002와1003도 같은 규칙으로 확인한다. 이름으로 연결하지 않으므로 동명이인이 있어도 학번별 수강을 섞지 않는다.',table('학습용 재연결 결과 · 강의실 변경 반영',['학번','이름','과목코드','과목명','강의실'],[['1001','박보성','C01','DB','401'],['1002','유성재','C01','DB','401'],['1003','박강열','C02','JAVA','202']]),marks=('학번별 수강',)),
 step('나머지 이상도 무엇이 사라지는지','독립된 가상 상황: 통합표의 마지막 C02 수강 행을 지우면 박강열의 수강뿐 아니라 JAVA가202호라는 사실도 잃는다. 새 과목을 수강생 없이 등록하려면 필수 수강 식별값 때문에 곤란할 수 있다. 학생·과목·수강을 나누면 서로의 존재를 불필요하게 묶지 않는다.',table('이상 현상 비교',['상황','원치 않은 영향'],[['C01의 한 행만 401로 변경','같은 과목 방이 401/301로 불일치'],['마지막 C02 수강 삭제','JAVA 202호 정보까지 유실'],['수강생 없는 새 과목 등록','수강 식별값을 함께 요구하는 구조라 곤란']]),marks=('독립된 가상 상황',))
 ],'FK 값의 반복은 연결을 보존하기 위한 정상 값이다. 반복되는 모든 숫자를 없애는 것이 정규화가 아니라 어느 값이 어떤 사실을 결정하는지 보고 사실의 저장 위치를 나누는 것이다.')],
 [('수정한 C01 행과 수정하지 않은 C01 행을 나란히 보자.','같은 C01의 방이 401과301로 달라지는 갱신 이상이다. 두 학생이 다른 사람인 것은 정상이며 과목의 방이라는 동일 사실이 달라진 것이 문제다.'),('지우려던 수강 사실 외에 어떤 사실이 그 행에만 있었는지 보자.','삭제 이상이다. 마지막 C02 수강 행을 지우면 JAVA 과목명과202호 사실도 같이 사라진다.'),('현재 우연히 같은 값인 것과 항상 지켜야 할 규칙이 같은가?','현재 값만으로 부족하다. 과목코드→과목명·강의실 같은 업무상 함수 종속을 확인해야 올바른 분해를 판단할 수 있다.')],
 [('화살표는 왼쪽을 오른쪽에 복사하라는 뜻이야?','아니다. 과목코드→강의실은 같은 과목코드이면 강의실이 하나로 정해진다는 업무 규칙이다. UPDATE의 대입 기호가 아니다.'),('정규화하면 자동으로401이 돼?','아니다. 표를 나누는 구조 개선과 강의실 변경은 별도다. 이 원본 결과는 변경 후 값401을 함께 반영했다.'),('그림에서는301인데?','기존 정규화 그림은 박강열·양지훈과 DB·JAVA를 쓰는 다른 예제다. 이 강의 원본은 박보성·유성재·박강열과 C01·C02이므로 각 표의 값을 따로 따라간다.')],
 ['삽입 이상에서 등록 불가능이라는 판단은 수강 식별값 등 필수 규칙에 달려 있다. 원문에 DDL이 없으므로 구체적인 DB 오류 코드를 만들지 않는다.'],notes=['원본 결과에서 301→401의 업무 변경이 이미 반영되어 있어 구조 변경만의 효과와 분리하여 설명했다.'],sources=[NORMAL])

lid='1-2-06'
lesson(lid,'이름과 학과명이 반복되는 이유를 종속 방향으로 찾고 3NF와 BCNF의 차이를 실제 후보키로 구별하자.',
 '두 개의 독립된 개념 예제다. 첫 예제는 성적통합을 학생·학과·성적으로 나누고 두 번째 예제는 학생·과목·강사의 후보키를 분석한다. SQL 실행 단계로 가장하지 않는다.',(19,24),[
 example(lid,0,'이승현이 DB·JAVA를 들을 때 이름과 학과 정보를 여러 행에 반복 관리하지 않게 한다.','개념: 부분 종속과 이행 종속을 분리한 3NF 구조를 해석한다.',
 ['학번→이름·학과코드, 학과코드→학과명, (학번,과목)→점수라는 세 업무 규칙을 사용한다.','한 수강을 (학번,과목)으로 구별하는 범위이며 반복 학기·분반은 이 원본에 없다.'],[
 step('키 전체가 필요한 점수','1001 이승현은 DB90, JAVA80이다. 학번만으로 점수 하나를 고르지 못하고 과목까지 필요하다. DB만으로도 1001의90과1002 박상현의70을 구별하지 못한다. 그래서 점수는 (학번,과목) 전체에 종속된다.',original(lid),marks=('DB90, JAVA80','학번,과목')),
 step('학번만으로 정해지는 이름','1001이 DB를 듣든 JAVA를 듣든 이름은 이승현, 학과코드는 D01이다. 이 둘은 키 일부인 학번으로 정해진다. 2NF를 위해 성적에는 학번·과목·점수를 남기고 학생 사실을 분리한다.',table('2NF 단계의 학생 정보 · 중간 구조',['학번','이름','학과코드','학과명'],[['1001','이승현','D01','컴퓨터'],['1002','박상현','D02','전자']]),marks=('키 일부인 학번',)),
 step('학생표 안에 남은 간접 종속','학번1001→학과코드D01→학과명컴퓨터 순으로 정해진다. 학과명은 학과코드의 사실이므로 학과코드·학과명을 학과표에 따로 둔다. 학생표에는 어느 학과인지 연결할 D01만 남긴다.',result(lid,0,1),marks=('학과코드D01','학과명컴퓨터')),
 step('분해 후 학생의 소속 연결','학생표의 (1001,이승현,D01),(1002,박상현,D02)에서 D01·D02를 학과표에 연결한다. 학과명을 학생표에서 분리했어도 이승현이 컴퓨터 학과라는 사실은 복원 가능하다.',result(lid,0,0),marks=('복원 가능',)),
 step('성적 세 건은 그대로','성적표에는 1001 DB90,1001 JAVA80,1002 DB70이 모두 남는다. 학생.학번을 연결해 이름을 읽고 학생.학과코드를 학과표에 연결해 학과명을 읽으면 원래 성적통합의 세 사실을 얻는다.',result(lid,0,2),marks=('성적통합의 세 사실',)),
 step('1NF는 글자를 못 나눈다는 뜻이 아니다','각 칸을 업무에서 하나의 값으로 다루는 것이 1NF의 출발점이다. 현재 과목 칸에는 DB와JAVA가 각각 별도 수강 행에 있다. 한 칸에 과목 목록을 넣는 상황과 이름 문자열을 글자별로 나눌 수 있는 상황은 다르다.',marks=('각각 별도 수강 행',))
 ],'2NF는 비주요 속성의 후보키 일부에 대한 종속을 본다. 대표 PK가 단일 컬럼이라는 사실만으로 다른 복합 후보키까지 무시해 언제나 2NF라고 결론내리지 않는다.'),
 example(lid,1,'3NF의 주요 속성 예외와 BCNF의 더 엄격한 결정자 조건을 비교한다.','개념: 수강지도에서 후보키·주요 속성·강사→과목을 분석한다.',
 ['규칙은 (학생,과목)→강사와 강사→과목이다. 한 학생의 같은 과목 담당 강사는 하나라는 원문 전제를 쓴다.','여기서 학생·강사 이름이 원본의 식별값 역할을 한다. 실제 시스템에서 동명이인이 가능하면 학생ID·강사ID가 필요하지만 원본 컬럼을 몰래 바꾸지 않는다.'],[
 step('세 행에서 규칙 방향 찾기','양지훈 강사는 이승현과 박상현 두 학생에게 DB를 담당한다. 양지훈을 알면 과목DB는 알지만 학생 한 명까지는 못 고른다. 유성재는 이승현의 JAVA 담당이다.',original(lid,1),marks=('과목DB는 알지만 학생 한 명까지는 못 고른다',),rows=(0,1)),
 step('첫 후보키: 학생과 과목','이승현과 DB를 함께 알면 담당은 양지훈이다. 이승현만으로는 DB/JAVA 두 수강이므로 부족하고 DB만으로도 두 학생이 있어 부족하다. 원문 규칙에 따라 학생·과목 조합이 최소 식별 기준이다.',table('후보키 확인',['입력 기준','추가로 결정되는 값','판정'],[['학생 + 과목','강사','후보키'],['학생만','과목·강사 한 건 불명','부족'],['과목만','학생 한 건 불명','부족']]),marks=('학생·과목 조합',)),
 step('두 번째 후보키: 학생과 강사','학생이 이승현이고 강사가 양지훈이면 강사→과목 규칙으로 DB를 얻는다. 따라서 (학생,강사)도 세 속성을 모두 결정한다. 학생은 두 후보키에, 과목과강사는 각각 한 후보키에 포함되어 세 속성 모두 주요 속성이다.',table('주요 속성 확인',['속성','포함되는 후보키'],[['학생','학생+과목 / 학생+강사'],['과목','학생+과목'],['강사','학생+강사']]),marks=('세 속성 모두 주요 속성',)),
 step('3NF와 BCNF가 갈리는 한 종속','강사→과목에서 강사는 학생까지 정하지 못하므로 슈퍼키가 아니다. 하지만 오른쪽 과목은 주요 속성이어서 3NF 조건의 예외를 만족한다. BCNF에는 그 예외가 없어 이 비자명 종속 때문에 위반한다.',table('같은 종속을 두 기준으로 검사',['검사','강사→과목의 판단','결론'],[['3NF','오른쪽 과목이 주요 속성','충족'],['BCNF','왼쪽 강사가 슈퍼키 아님','위반']]),marks=('오른쪽 과목은 주요 속성','슈퍼키가 아니다')),
 step('분해된 표에서 강사의 과목 한 번 저장','강사과목에 양지훈-DB,유성재-JAVA를 두고 학생강사에 이승현-양지훈,박상현-양지훈,이승현-유성재를 둔다. 강사로 다시 연결하면 원본 세 행이 복원된다.',result(lid,1,0),marks=('원본 세 행이 복원',)),
 step('무손실과 종속 보존은 다른 검사','학생강사 표만 보면 이승현이 서로 다른 두 강사를 선택하는 것이 허용될 수 있다. 그 강사들이 같은 과목을 맡는지까지 검사하려면 강사과목을 같이 봐야 한다. 따라서 분해가 무손실이어도 (학생,과목)→강사 규칙을 두 표 각각의 키만으로 모두 보장하는 것은 아니다.',result(lid,1,1),marks=('무손실이어도','두 표 각각의 키만으로'))
 ],'BCNF의 정확한 조건은 모든 비자명 함수 종속의 결정자가 슈퍼키라는 것이다. 후보키만이라고 좁히거나 3NF를 이행 종속이 단 하나도 없다는 말로만 외우지 않는다.')],
 [('복합키 두 항목이 다 필요한지 하나만으로 충분한지 보자.','학번만으로 이름이 정해지므로 복합키 (학번,과목)의 일부에 의존하는 부분 함수 종속이다. 과목별로 달라지는 점수와 다르다.'),('학번에서 학과명으로 가는 중간 항목을 찾아보자.','학과코드가 중간에 있다. 학과코드→학과명을 학과표로 분리하여 학생표의 비키를 거친 이행 종속을 정리하는 3NF 사례다.'),('결정자가 전체 행을 구별할 수 있는지가 핵심이다.','슈퍼키다. 최소성까지 요구하는 후보키만으로 좁히면 안 된다. 두 번째 예제의 강사는 학생을 결정하지 못해서 이 조건을 충족하지 않는다.')],
 [('함수 종속의 화살표가 값이 이동한다는 뜻이야?','아니다. 같은 왼쪽 값이 나오면 오른쪽 값도 같아야 한다는 규칙이다. 테이블 간 데이터 복사 명령이 아니다.'),('왜 학생+강사도 키야?','강사가 과목을 결정하므로 학생과강사를 알고 있으면 학생·과목·강사 세 항목을 다 알 수 있다.'),('4NF·5NF도 여기서 실행해?','아니다. 원본은 다치 종속·조인 종속이라는 심화 이름을 소개한다. 이 두 예제로 4NF·5NF의 모든 조건을 검증했다고 보지 않는다.')],
 ['PDF 20쪽 연락처표는 회원번호1001이 반복되므로 회원번호 하나만 PK라는 표시로 해석하면 모순이다. 연락처까지 포함한 복합키나 별도 식별자 전제가 필요하다. 원본 표는 변경하지 않고 주의로 남긴다.','PDF의 BCNF 후보키 표현은 슈퍼키 조건으로 정확히 보완한다. 5NF를 모든 가능한 정규형의 마지막이라고 일반화하지 않는다.'],
 notes=['PDF 1-2 20쪽 PK 표시와 중복 회원번호를 렌더 이미지에서도 확인했다. 추가 해설은 기존 두 앱 예제와 PDF 문제를 별도 자료로 유지한다.'],sources=[NORMAL])

lid='1-2-07'
lesson(lid,'주문상세 합계를 매번 계산하는 일과 계산값을 실제 저장해 유지하는 일을 구별하자.',
 '원본 SQL은 주문상세를 읽어 합계를 보여 주는 SELECT다. 저장합계는 결과 열 별칭이며 이 SQL만으로 주문표에 값을 저장하지 않는다. 반정규화의 저장·갱신 비용은 별도 가정으로 비교한다.',(25,27),[
 example(lid,0,'주문101의 금액을 빠르게 보여 주려 할 때 집계값 저장의 장점과 일관성 부담을 알아본다.','조회: 주문상세를 주문번호별로 합산한다. 저장·변경은 설명용 별도 가정이다.',
 ['원본 주문상세는101 키보드30000,101 마우스20000,102 모니터150000이다. 금액은 합산 가능한 숫자라는 전제다.','주문요약이라는 결과 제목과 저장합계라는 별칭은 실제 저장 테이블 생성문이 아니다.','마우스25000 변경은 원본 설명의 후속 가정이며 현재 SELECT 실행 전에 원본20000을 몰래 바꾸지 않는다.'],[
 step('전체 코드가 실제로 하는 일','SELECT는 보여 달라는 요청이다. FROM 주문상세는 기존 주문상세를 읽는다. 주문번호·금액은 그 표의 컬럼이고 SUM은 여러 금액을 더하는 함수다. 이 문장에는 INSERT나 UPDATE가 없다.',original(lid),('FROM 주문상세','SUM(금액)'),('기존 주문상세','INSERT나 UPDATE가 없다')),
 step('주문번호로 묶기','GROUP BY 주문번호는101 두 행과102 한 행을 각각 같은 주문으로 묶는다. 품목 이름으로 묶지 않으므로 키보드와마우스는 달라도 주문101 합계의 같은 그룹이다.',table('학습용 그룹 확인',['주문번호','포함 품목','금액 목록'],[['101','키보드 · 마우스','30000 · 20000'],['102','모니터','150000']]),('GROUP BY 주문번호',),('주문101 합계의 같은 그룹',)),
 step('실제 금액 계산','101은30000+20000=50000이고102는150000 한 값의 합이다. SUM(금액)은 그룹 안 금액을 더한다. 원본 상세 세 행의 금액은 조회 때문에 바뀌지 않는다.',table('학습용 집계 과정',['주문번호','계산','합계'],[['101','30000 + 20000','50000'],['102','150000','150000']]),('SUM(금액)',),('원본 상세 세 행의 금액은 조회 때문에 바뀌지 않는다',)),
 step('별칭과 표시 순서','AS 저장합계는 합계 결과 열을 저장합계라는 이름으로 보여 준다는 뜻이다. 실제 금액 컬럼을 이름 변경하거나 저장하는 명령이 아니다. ORDER BY 주문번호로101 다음102 순서를 지정한다.',result(lid),('AS 저장합계','ORDER BY 주문번호'),('실제 금액 컬럼','101 다음102')),
 step('저장한다고 가정했을 때의 갱신 부담','별도 저장 가정: 주문101의 합계50000을 보관했다가 마우스 금액만20000→25000으로 수정하면 실제 합계는55000이다. 저장값50000을 그대로 두면5000만큼 어긋난다. 원본 SELECT만 실행해 이 저장 불일치가 생겼다는 뜻은 아니다.',table('설명용 독립 상태 비교',['상태','상세 합계','별도 저장값','판정'],[['처음 저장했다고 가정','50000','50000','일치'],['상세만 변경한 시도','55000','50000','불일치'],['저장값도 함께 변경','55000','55000','일치']]),marks=('별도 저장 가정','5000만큼 어긋난다')),
 step('유지할 주문과 설계 판단','마우스는 주문101의 품목이라102 모니터150000은 그대로다. 저장합계를 두면 읽을 때 계산을 줄일 수 있지만 변경 시 함께 갱신할 책임이 생긴다. 실제 성능은 조회량·행 수·인덱스 등을 측정해야 하며 이 작은 표로 속도 향상을 측정한 것은 아니다.',table('변경 가정의 주문별 영향',['주문번호','이전 합계','이후 합계','판정'],[['101','50000','55000','변경'],['102','150000','150000','유지']]),marks=('102 모니터150000은 그대로',))
 ],'정규화는 사실의 중복 관리 문제를 줄이고, 반정규화는 측정한 조회 문제를 해결하려 일부 중복 등을 선택한다. 수평 분할은 행, 수직 분할은 열을 나누는 기준이며 모든 분할이 정규형 위반은 아니다.')],
 [('상세를 다시 더한 값과 별도로 저장한 값이 같은지 보자.','마우스가25000이면101의 합은55000인데 저장값이50000이면 불일치다. 102는 해당 변경과 관련 없어150000을 유지한다.'),('느린 원인이 조인·스캔·인덱스 중 무엇인지 알 수 있는가?','원인을 측정하지 않고 무조건 반정규화하지 않는다. 쿼리·인덱스·실행계획·사용 패턴과 갱신 부담을 비교해야 한다.'),('나누는 기준이 주문의 연도 값인가 컬럼 목록인가?','연도 조건에 따라 행을 나누므로 수평 분할이다. 이름·상세설명처럼 열 묶음을 나누는 수직 분할과 다르다.')],
 [('저장합계라고 써 있는데 저장 안 한 거야?','맞다. 이 SQL에서 저장합계는 조회 결과의 이름이다. 실제 보관하려면 별도 테이블·컬럼과 입력·갱신 작업이 필요하다.'),('정규화하면 항상 느려지고 반정규화하면 항상 빨라져?','아니다. 어떤 데이터를 얼마나 읽고 변경하는지에 따라 달라진다. 이 예제는 일관성 비용을 설명하며 실제 성능 비교를 실행한 자료가 아니다.')],
 ['PDF의 무결성 자동 보장은 정규화만으로 모든 오류가 차단된다는 뜻으로 읽지 않는다. 키·제약조건·트랜잭션·업무 검증도 필요하다.','저장합계를 실제 저장으로 설명하는 오해를 막기 위해 조회 단계와 후속 변경 가정을 나누었다.'],
 [term('SUM','함수','sum은 합계','주문번호별 금액을 더한다.'),term('GROUP BY','키워드','같은 기준별로 묶다','주문번호101의 두 품목을 같은 그룹으로 본다.'),term('AS','키워드','무엇이라는 이름으로','SUM 결과 열의 표시 이름을 저장합계로 정한다.'),term('저장합계','결과 열 별칭','이 쿼리에서 정한 표시 이름','테이블에 저장하라는 명령이 아니다.')],
 notes=['원본 title·SQL·결과 이름은 모두 보존했다. SELECT만 있는 원본을 실제 저장 구현으로 오인하지 않도록 명시했다.'],sources=[NORMAL])

# Prerequisite words are explained at the lesson where they are actually used.
for _lid,_terms in {
 '1-1-03':[
   term('PK','제약 역할 약어','Primary Key · 기본키','학번으로 학생 한 명을 구별하도록 정한 대표 키다.'),
   term('NUMBER(6)','Oracle 자료형','숫자를 저장하는 자료형과 정밀도','여기서 6은 학번의 숫자 정밀도다. 행 여섯 개를 만들거나 번호를 자동 생성하지 않는다.'),
   term('VARCHAR2(30 CHAR)','Oracle 자료형','길이가 달라지는 문자열','이름을 문자 수 기준 최대30으로 정의한 물리 설계 조각이다.'),
   term('NOT NULL','제약조건','NULL이 아니다 · 값의 부재를 금지','이름 값을 빠뜨리지 않도록 한다. 동명이인을 금지하는 규칙은 아니다.')],
 '1-1-05':[term('ERD','그림 약어','Entity-Relationship Diagram · 개체와 관계를 그린 그림','학생·과목·수강의 대상과 속성·연결 규칙을 보여 준다.'),term('0..N','범위 기호','최소0, 최대는 여러 개','학생 한 명이 아직 수강이 없거나 여러 수강을 가질 수 있다는 규칙을 표현한다.')],
 '1-1-06':[term('Entity','영어 용어','관리하는 대상의 종류 또는 집합','여기서는 학번·이름·학과를 관리하는 학생이다.'),term('Instance','영어 용어','그 종류에 속하는 구체적인 사례','1002·양지훈·전자로 이루어진 학생 한 행을 가리킨다.'),term('Attribute','영어 용어','대상을 설명하는 항목','학생의 학번·이름·학과가 각각 속성이다.')],
 '1-1-07':[term('차수(Degree)','개념','열의 수','현재 학생표의 학번·이름·학과·학년 네 속성을 세면4다.'),term('카디널리티(Cardinality)','개념','이 문맥에서는 행의 수','이승현·양지훈·박보성의 정보 묶음 세 행을 세면3이다.'),term('튜플(Tuple)','개념','한 행을 이루는 값의 묶음','1001·이승현·컴퓨터·4 전체가 한 튜플이지 이름 한 값만이 튜플은 아니다.')],
 '1-1-08':[term('학생.학과코드','소속 표기','점 왼쪽은 표, 오른쪽은 그 표의 열','현재 설명에서 참조값을 담은 자식 학생표의 학과코드를 가리킨다.'),term('학과.학과코드','소속 표기','점 왼쪽은 표, 오른쪽은 그 표의 열','참조받는 부모 학과표의 코드다. 학생.학과코드와 이름이 같아도 다른 열이다.')],
 '1-1-09':[term('복합키','키 구성','여러 속성을 함께 묶은 하나의 키','수강 한 건을 학번과과목코드의 조합으로 구별한다. 문자열 합계가 아니다.')],
 '1-2-05':[term('→','종속 기호','왼쪽 값을 정하면 오른쪽이 하나로 정해짐','과목코드→강의실은 같은 C01에 방을 하나로 정한다는 업무 규칙이다. 값을 대입하는 SQL이 아니다.')],
 '1-2-06':[
   term('후보키','선행 개념','행 전체를 유일하게 고르는 최소 속성 집합','첫 예제의 학번+과목, 둘째 예제의 학생+과목과학생+강사를 판단한다.'),
   term('슈퍼키','선행 개념','행 전체를 유일하게 고를 수 있는 속성 집합','BCNF에서 종속 화살표 왼쪽이 전체 행을 결정하는지 확인할 기준이다.'),
   term('비주요 속성','개념','어떤 후보키에도 포함되지 않은 항목','첫 성적통합 예제의 이름·점수·학과코드·학과명은 (학번,과목) 후보키 바깥 항목이다.'),
   term('비자명 함수 종속','개념','오른쪽에 이미 왼쪽에 포함된 것만 있는 종속은 제외하고 보는 규칙','강사→과목은 강사만으로 새 항목인 과목을 결정하므로 BCNF 검사 대상이다.'),
   term('무손실 분해','개념','표를 나누어도 연결하면 원래 사실을 정확히 되찾음','학생강사와강사과목을 강사로 연결해 수강지도 세 행을 복원한다.')],
}.items():
    for _t in _terms:
        GUIDES[_lid]['terms']=[t for t in GUIDES[_lid]['terms'] if t['token']!=_t['token']]+[_t]

# Explicit links to the relevant value cells; never infer highlights from colors.
for _lid,_ex,_stage,_cells in [
    ('1-1-01',0,1,[(0,2),(1,2),(2,2)]),
    ('1-1-02',0,3,[(0,2),(1,2)]),
    ('1-1-07',0,2,[(0,0),(0,2),(2,0),(2,2)]),
    ('1-1-08',0,0,[(0,0)]),
    ('1-1-08',0,1,[(0,2),(1,2)]),
    ('1-1-08',0,2,[(2,2),(2,3)]),
    ('1-2-01',0,2,[(0,1),(0,2),(2,1),(2,2)]),
    ('1-2-02',0,3,[(2,2),(2,3)]),
    ('1-2-03',0,1,[(0,0),(0,4)]),
    ('1-2-03',0,2,[(0,2),(0,4)]),
    ('1-2-03',0,3,[(0,3),(0,4)]),
    ('1-2-03',0,4,[(1,0),(1,4)]),
    ('1-2-05',0,1,[(0,3),(1,3)]),
    ('1-2-05',0,2,[(0,2)]),
    ('1-2-06',0,2,[(0,0),(0,1)]),
    ('1-2-06',1,3,[(0,1),(0,2),(1,1),(1,2)]),
    ('1-2-07',0,2,[(0,1),(0,2)]),
    ('1-2-07',0,4,[(1,1),(1,2),(1,3)]),
    ('1-2-07',0,5,[(0,1),(0,2),(0,3)]),
]:
    GUIDES[_lid]['examples'][_ex]['steps'][_stage]['focusCells']=[dict(row=r,column=c) for r,c in _cells]

def validate_draft():
    expected={l['id'] for l in PACK['lessons'] if l['partId'] in {'1-1','1-2'}}
    assert set(GUIDES)==expected
    seen=set()
    for lid,g in GUIDES.items():
        assert g['source']==LESSONS[lid]
        assert [e['exampleId'] for e in g['examples']]==[e['id'] for e in LESSONS[lid]['examples']]
        for ex, src in zip(g['examples'],LESSONS[lid]['examples']):
            assert ex['exampleId'] not in seen;seen.add(ex['exampleId'])
            for s in ex['steps']:
                for f in s['codeFocus']:
                    assert f['needle'] in src['sql'],(lid,f)
                for h in s['highlights']:
                    assert h in s['text'],(lid,h,s['text'])
                t=s['table']
                if t:
                    assert all(len(r)==len(t['columns']) for r in t['rows'])
                    assert all(c is None or isinstance(c,str) for r in t['rows'] for c in r)
                    assert all(0<=r<len(t['rows']) for r in s['focusRows'])
                    assert all(0<=c['row']<len(t['rows']) and 0<=c['column']<len(t['columns']) for c in s['focusCells'])
                else:
                    assert not s['focusRows'] and not s['focusCells']
        assert [q['checkId'] for q in g['checkGuides']]==[q['id'] for q in LESSONS[lid]['selfChecks']]
    assert SOURCE_PATH.read_bytes()==SOURCE_BYTES

def verify_queries():
    records=[]
    for lid in ['1-1-01','1-2-07']:
        ex=LESSONS[lid]['examples'][0]
        db=sqlite3.connect(':memory:')
        t=ex['tables'][0]
        numeric={'학번','점수','주문번호','금액'}
        columns=', '.join('"'+c+'" '+('INTEGER' if c in numeric else 'TEXT') for c in t['columns'])
        db.execute('CREATE TABLE "'+t['title']+'" ('+columns+')')
        db.executemany('INSERT INTO "'+t['title']+'" VALUES ('+','.join('?' for _ in t['columns'])+')',t['rows'])
        got=[[str(x) if x is not None else None for x in row] for row in db.execute(ex['sql']).fetchall()]
        assert got==ex['results'][0]['rows'],(lid,got)
        records.append(dict(lessonId=lid,exampleId=ex['id'],engine='SQLite '+sqlite3.sqlite_version,rows=got,result='PASS'))
        for e in GUIDES[lid]['examples']:
            e['verification']=f'이번 추가 해설 작업에서 원본 SQL과 입력표를 SQLite {sqlite3.sqlite_version} 메모리 DB로 실행해 원본 결과표와 값·열 순서·행 순서를 대조했습니다. Oracle·SQL Server에서 실행한 결과는 아닙니다. 별도 저장·수정 가정은 논리 검산이며 이 SELECT의 실행 결과와 구분합니다.'
        db.close()
    return records

def verify_concepts():
    """Independent calculations from original values, not a SQL-engine claim."""
    records=[]
    # PK/range/FK candidates are separate attempts against the same base state.
    ex=LESSONS['1-2-03']['examples'][0]
    dept={r[0] for r in ex['tables'][0]['rows']}
    existing={r[0] for r in ex['tables'][1]['rows']}
    decisions=[]
    for sid,name,year,dep in ex['tables'][2]['rows']:
        allowed=sid not in existing and name is not None and 1<=int(year)<=4 and dep in dept
        decisions.append('허용' if allowed else '거절')
    assert decisions==[r[1] for r in ex['results'][0]['rows']]
    records.append(dict(exampleId=ex['id'],check='independent constraint-predicate evaluation',decisions=decisions,result='PASS'))
    # 2NF/3NF example reconstructs every original tuple exactly.
    ex=LESSONS['1-2-06']['examples'][0]
    students={r[0]:r[1:] for r in ex['results'][0]['rows']}
    depts={r[0]:r[1] for r in ex['results'][1]['rows']}
    rebuilt=[]
    for sid,subject,score in ex['results'][2]['rows']:
        name,dep=students[sid]
        rebuilt.append([sid,name,subject,score,dep,depts[dep]])
    assert sorted(rebuilt)==sorted(ex['tables'][0]['rows'])
    records.append(dict(exampleId=ex['id'],check='natural rejoin of authored decomposition',rows=rebuilt,result='PASS'))
    # FD closure derives both minimal keys; each current tuple also rejoins.
    from itertools import combinations
    attrs={'학생','과목','강사'}
    fds=[({'학생','과목'},{'강사'}),({'강사'},{'과목'})]
    def closure(initial):
        found=set(initial)
        while True:
            before=found.copy()
            for lhs,rhs in fds:
                if lhs<=found:found|=rhs
            if found==before:return found
    keys=[]
    for size in range(1,4):
        for c in combinations(sorted(attrs),size):
            candidate=set(c)
            if closure(candidate)==attrs and not any(k<=candidate for k in keys):keys.append(candidate)
    assert {frozenset(k) for k in keys}=={frozenset({'학생','과목'}),frozenset({'학생','강사'})}
    assert closure({'강사'})=={'강사','과목'}
    ex=LESSONS['1-2-06']['examples'][1]
    teachers=dict(ex['results'][0]['rows'])
    rebuilt=[[student,teachers[teacher],teacher] for student,teacher in ex['results'][1]['rows']]
    assert sorted(rebuilt)==sorted(ex['tables'][0]['rows'])
    records.append(dict(exampleId=ex['id'],check='FD closure and lossless reconstruction',candidateKeys=[sorted(k) for k in keys],teacherClosure=sorted(closure({'강사'})),result='PASS'))
    # The anomalies example includes a stated room change, not pure decomposition.
    ex=LESSONS['1-2-05']['examples'][0]
    students=dict(ex['results'][0]['rows']);courses={r[0]:r[1:] for r in ex['results'][1]['rows']}
    rebuilt=[[sid,students[sid],course,*courses[course]] for sid,course in ex['results'][2]['rows']]
    expected=[[*r[:4], '401' if r[2]=='C01' else r[4]] for r in ex['tables'][0]['rows']]
    assert sorted(rebuilt)==sorted(expected)
    records.append(dict(exampleId=ex['id'],check='rejoin after explicit C01 301-to-401 business change',result='PASS'))
    assert 30000+20000==50000 and 30000+25000==55000
    records.append(dict(exampleId='1-2-07-E01',check='hypothetical stored-aggregate arithmetic',before=50000,after=55000,difference=5000,result='PASS'))
    return records

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--write',action='store_true');args=ap.parse_args()
    validate_draft(); engines=verify_queries(); concepts=verify_concepts()
    stats=dict(lessons=len(GUIDES),examples=sum(len(g['examples']) for g in GUIDES.values()),
               checks=sum(len(g['checkGuides']) for g in GUIDES.values()),steps=sum(len(e['steps']) for g in GUIDES.values() for e in g['examples']),
               sourceSha256=hashlib.sha256(SOURCE_BYTES).hexdigest(),engineChecks=engines,conceptChecks=concepts)
    if args.write:
        dest=ROOT/'content/lesson-guides';dest.mkdir(exist_ok=True)
        for lid,g in GUIDES.items():(dest/f'{lid}.json').write_text(json.dumps(g,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        ev=ROOT/'evidence/explanation-upgrade-20261012';ev.mkdir(exist_ok=True)
        record=dict(group='modeling',stats=stats,scope='기존 16강의 17예제·48자기점검에 별도 상세 해설. 원본 PDF 문항 전체를 새로 옮기거나 재채점한 것이 아님.',
          pdfRead=dict(sections={'1-1':'1-27','1-2':'1-27'},visualPages=['1-1:18','1-1:21','1-1:27','1-2:20']),
          visualReview='기존 visual-01~10 PNG 및 연결 안내를 확인. 데이터가 다른 원본 예제와 섞지 않음. 새 이미지 생성 없음.',
          lessons=[dict(lessonId=lid,title=g['source']['title'],missingBefore=DEFICIENCIES[lid],
            action=g['purpose'],specificComparisons=[e['comparison'] for e in g['examples']],sourceCautions=g['reviewNotes']+g['pitfalls'],
            verification=[e['verification'] for e in g['examples']],unverified=['실제 앱 화면은 통합 담당자가 별도 검증','사람 전문가 검수·학습효과·실물 Galaxy 미검증']) for lid,g in GUIDES.items()])
        (ev/'modeling-review.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(write=args.write,**stats),ensure_ascii=False,indent=2))

if __name__=='__main__':main()
